window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[337]={"id":"337","numero":337,"titre":"Intoxications aiguës","objectifs":[{"id":"337-1","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les principales intoxications aiguës de l’adulte et de l’enfant","contenu":"<p>La toxicologie couvre un spectre très large : médicaments, plantes, champignons, produits ménagers, gaz toxiques (<span class=\"kw-etio\">CO</span>, fumées d'incendie), pesticides, morsures. <strong>Dogme</strong> — tout xénobiotique pouvant entrer dans le corps est potentiellement <span class=\"kw-etio\">toxique</span> : <strong>c'est la dose qui fait le poison</strong>.</p>\n      <table >\n        <thead><tr><th>Famille</th><th>Principaux toxiques en cause</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Médicaments</span> (forme la plus fréquente)</td>\n            <td>\n              <strong>Hypnotiques :</strong> <span class=\"kw-ttt\">benzodiazépines</span> et apparentés — <strong>1<sup>re</sup> classe en cause</strong><br>\n              <strong>Autres psychotropes :</strong> <span class=\"kw-ttt\">neuroleptiques</span> ; <span class=\"kw-ttt\">anti-H1</span> ; <span class=\"kw-ttt\">ISRS</span> ; <span class=\"kw-ttt\">antidépresseurs tricycliques</span><br>\n              <strong><span class=\"kw-ttt\">Antalgiques</span> :</strong> <span class=\"kw-ttt\">paracétamol</span> ; <span class=\"kw-ttt\">tramadol</span> ; <span class=\"kw-ttt\">morphine</span><br>\n              <strong>Plus rares :</strong> antiépileptiques ; <span class=\"kw-ttt\">lithium</span> ; <span class=\"kw-ttt\">cardiotropes</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Gaz toxiques</span></td>\n            <td><span class=\"kw-etio\">Monoxyde de carbone</span> — <strong>1<sup>re</sup> cause de décès par intoxication en France</strong> ; <span class=\"kw-etio\">fumées d'incendie</span> (CO + cyanure)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Drogues festives</span> (en recrudescence)</td>\n            <td><span class=\"kw-etio\">Cannabis</span> ; <span class=\"kw-etio\">cocaïne</span> ; <span class=\"kw-etio\">amphétamines</span> ; <span class=\"kw-etio\">nouvelles drogues de synthèse</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Distinction physiopathologique fondamentale, qui conditionne l'évaluation du <span class=\"kw-def\">pronostic</span> :</p>\n      <table >\n        <thead><tr><th>Type</th><th>Mécanisme et conséquences</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Toxiques fonctionnels</span></td>\n            <td>\n              Action <strong>pharmacologique</strong> via un récepteur cible ; <strong>pas de <span class=\"kw-clinique\">lésion</span> tissulaire</strong><br>\n              Toxicité <strong>dose-dépendante</strong> (relation dose-effet) ; effet <strong>réversible</strong> après élimination<br>\n              <strong>Exemples :</strong> psychotropes ; cardiotropes ; théophylline ; éthanol\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Toxiques lésionnels</span></td>\n            <td>\n              Produisent des <span class=\"kw-alerte\">lésions directes d'organe</span> ; gravité liée à la concentration <strong>dans l'organe cible</strong> (et non plasmatique)<br>\n              Symptômes <strong>retardés</strong>, phase initiale parfois asymptomatique ; persistent malgré la disparition du <span class=\"kw-etio\">toxique</span><br>\n              <strong>Exemples :</strong> <span class=\"kw-ttt\">paracétamol</span> (le plus typique) ; <span class=\"kw-ttt\">lithium</span> ; <span class=\"kw-ttt\">colchicine</span> ; métaux lourds\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 325 — Risque <span class=\"kw-etio\">médicamenteux</span>, <span class=\"kw-etio\">iatrogène</span></em></p>","frequence":0},{"id":"337-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les principales intoxications aux cardiotropes","contenu":"<p><span class=\"kw-clinique\">Les</span> intoxications aux <span class=\"kw-def\">cardiotropes</span> ont une <span class=\"kw-alerte\">mortalité de 15-20 %</span>. La gravité tient surtout aux molécules dotées d'un <span class=\"kw-alerte\">effet stabilisant de membrane</span> (retentissement hémodynamique : <span class=\"kw-def\">choc cardiogénique</span>).</p>\n      <table >\n        <thead><tr><th>Classe</th><th>Mécanisme et tableau</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-ttt\">β-bloquants</span></td>\n            <td><span class=\"kw-clinique\">Bradycardie</span> + <span class=\"kw-clinique\">hypotension</span> ; <span class=\"kw-clinique\">apnée</span> (avec le <span class=\"kw-ttt\">propranolol</span>) ; <span class=\"kw-clinique\">hypoglycémie</span> parfois ; effet stabilisant de membrane (<span class=\"kw-ttt\">propranolol</span>, acébutolol)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Inhibiteurs calciques non-dihydropyridiniques</span> (<span class=\"kw-ttt\">vérapamil</span>, diltiazem)</td>\n            <td>Bradycardisants et inotropes négatifs → <span class=\"kw-alerte\">choc cardiogénique</span> avec <span class=\"kw-clinique\">bradycardie</span> ; pourvoyeurs de troubles de conduction (<strong>effet stabilisant de membrane</strong>) ; <span class=\"kw-alerte\">mortalité élevée</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Inhibiteurs calciques dihydropyridiniques</span> (<span class=\"kw-ttt\">amlodipine</span>, nicardipine)</td>\n            <td>Tropisme quasi exclusivement vasculaire → <span class=\"kw-clinique\">vasoplégie isolée</span> ; <strong>pas d'effet stabilisant de membrane</strong></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Digitaliques</span> (<span class=\"kw-ttt\">digoxine</span>)</td>\n            <td>Inhibition de la pompe Na⁺/K⁺ → <span class=\"kw-bio\">hyperkaliémie</span> ; troubles de conduction (<span class=\"kw-clinique\">bradycardie</span>, BAV) ; <span class=\"kw-clinique\">tachycardie</span> atriale ; signes digestifs et visuels (dyschromatopsie jaune/vert)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Discriminant clé.</strong> Devant une intoxication par <span class=\"kw-ttt\">inhibiteur calcique</span>, distinguer d'emblée <span class=\"kw-ttt\">non-dihydropyridiniques</span> (bradycardisants, <span class=\"kw-alerte\">choc</span> + ESM) et <span class=\"kw-ttt\">dihydropyridiniques</span> (vasoplégie pure, pas d'ESM) — la prise en charge en dépend.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 234 — <span class=\"kw-def\">Insuffisance cardiaque</span></em></p>","frequence":0},{"id":"337-3","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie des principales intoxications aiguës chez l’enfant et l’adulte","contenu":"<p><span class=\"kw-clinique\">Les</span> intoxications sont la <strong>1<sup>re</sup> cause d'admission à l'hôpital de l'adulte jeune de <span class=\"kw-chiffre\">moins de 30 ans</span></strong>.</p>\n      <table >\n        <thead><tr><th>Item</th><th>Données</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Circonstances</strong></td>\n            <td>\n              <strong>Intoxication médicamenteuse volontaire (IMV) :</strong> <span class=\"kw-chiffre\">90 %</span> des cas, contexte de tentative de suicide<br>\n              <strong>Surdosage :</strong> 2<sup>e</sup> position (erreur de prise, <span class=\"kw-ci\">insuffisance rénale</span>, sujet âgé)<br>\n              <strong>Accidentelle :</strong> enfant, sujet âgé — <strong>criminelle :</strong> rare\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Médicaments en cause</strong></td>\n            <td><span class=\"kw-ttt\">Benzodiazépines</span> et hypnotiques = 1<sup>re</sup> classe ; co-intoxication à l'<span class=\"kw-etio\">éthanol</span> fréquente (<span class=\"kw-chiffre\">&gt; 40 %</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Présentations des IMV</strong></td>\n            <td>\n              Contexte clair d'ingestion de psychotrope : <span class=\"kw-chiffre\">~85 %</span><br>\n              <span class=\"kw-etio\">Toxique</span> fonctionnel cardiaque ou lésionnel évident : <span class=\"kw-chiffre\">~10 %</span><br>\n              <span class=\"kw-clinique\">Coma</span> ou <span class=\"kw-alerte\">défaillance</span> d'organe sans contexte évident : minorité\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Pronostic</span></strong></td>\n            <td><span class=\"kw-def\">Mortalité</span> hospitalière après traitement bien conduit <span class=\"kw-chiffre\">&lt; 3/1000</span> ; <span class=\"kw-alerte\">récidive fatale</span> dans <span class=\"kw-chiffre\">5 à 10 %</span> des cas dans l'année — d'où l'évaluation psychiatrique imposée</td>\n          </tr>\n          <tr>\n            <td><strong>Enfant</strong></td>\n            <td>\n              <span class=\"kw-chiffre\">2<sup>e</sup></span> cause d'accidents de la vie courante (après <span class=\"kw-clinique\">les</span> traumatismes, devant les brûlures)<br>\n              <span class=\"kw-def\">Mortalité</span> <span class=\"kw-chiffre\">10-12 cas/an</span>, essentiellement entre <span class=\"kw-chiffre\">1 et 4 ans</span><br>\n              Produits en cause : <span class=\"kw-ttt\">médicaments</span> <span class=\"kw-chiffre\">~60 %</span> · produits ménagers <span class=\"kw-chiffre\">~25 %</span> · cosmétiques <span class=\"kw-chiffre\">5-10 %</span> ; le plus souvent produit unique ingéré accidentellement\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Recrudescence festive.</strong> Hausse des intoxications « festives » : <span class=\"kw-etio\">cannabis</span>, <span class=\"kw-etio\">cocaïne</span>, <span class=\"kw-etio\">amphétamines</span>, nouvelles drogues de synthèse.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 353 — Risque et conduite suicidaire</em></p>","frequence":0},{"id":"337-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques des intoxications aiguës","contenu":"<p><strong>Objectif EDN majeur (4 ⭐).</strong> Le diagnostic clinique repose sur la recherche d'un <span class=\"kw-def\">toxidrome</span> = ensemble de signes cliniques et biologiques cohérents avec une famille pharmacologique. <strong>La profondeur d'un <span class=\"kw-clinique\">coma</span> n'a aucune valeur d'orientation étiologique</strong> — ce sont <span class=\"kw-clinique\">les</span> <strong>modifications neurovégétatives</strong> qui orientent.</p>\n      <p>Manifestations cliniques générales, par appareil :</p>\n      <table >\n        <thead><tr><th>Appareil</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Neurologique</strong></td>\n            <td><span class=\"kw-clinique\">Troubles de la conscience</span> au premier plan (surtout psychotropes) — toujours rechercher un traumatisme crânien et des signes de focalisation</td>\n          </tr>\n          <tr>\n            <td><strong>Respiratoire</strong></td>\n            <td><span class=\"kw-clinique\">Hypoventilation centrale</span> (<span class=\"kw-clinique\">bradypnée</span>, respiration superficielle) ; <span class=\"kw-clinique\">pneumopathie d'inhalation</span> ; <span class=\"kw-def\">OAP</span> lésionnel</td>\n          </tr>\n          <tr>\n            <td><strong>Cutanéo-muqueux</strong></td>\n            <td><span class=\"kw-clinique\">Teinte cochenille</span> (intoxication massive au CO) ; <span class=\"kw-clinique\">cyanose ardoisée</span> (méthémoglobinémie) ; haleine alcoolisée/acétone ; escarres de compression</td>\n          </tr>\n          <tr>\n            <td><strong>Thermorégulation</strong></td>\n            <td><span class=\"kw-clinique\">Hyperthermie</span> (salicylés, sympathomimétiques, anticholinergiques) ; <span class=\"kw-clinique\">hypothermie</span> (<span class=\"kw-etio\">alcool</span>, exposition prolongée)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><span class=\"kw-clinique\">Les</span> 5 toxidromes principaux à reconnaître :</p>\n      <table >\n        <thead><tr><th>Toxidrome</th><th>Toxiques typiques</th><th>Signes clés</th><th>Gravité</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Morphinique</span> / opioïde (<span class=\"kw-clinique\">coma</span> calme)</td>\n            <td>Opioïdes (palier 2-3) ; héroïne ; fentanyls</td>\n            <td>Triade : <span class=\"kw-clinique\">coma calme hypotonique aréflexique</span> + <span class=\"kw-clinique\">myosis serré bilatéral</span> + <span class=\"kw-clinique\">bradypnée</span> <span class=\"kw-chiffre\">≤ 10/min</span> ; globe urinaire</td>\n            <td><span class=\"kw-alerte\">Détresse respiratoire</span> → <span class=\"kw-alerte\">ACR</span> hypoxique</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Myorelaxation</span> (<span class=\"kw-clinique\">coma</span> calme)</td>\n            <td>Benzodiazépines ; alcools ; barbituriques ; carbamates</td>\n            <td><span class=\"kw-clinique\">Coma calme hypotonique</span> ; <span class=\"kw-clinique\">hyporéflexie</span> ; <span class=\"kw-clinique\">bradypnée</span> ; <strong>pupilles normales</strong>, pas de localisation</td>\n            <td><span class=\"kw-alerte\">Obstruction des VAS</span> → <span class=\"kw-alerte\">asphyxie</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Anticholinergique</span> / atropinique (<span class=\"kw-clinique\">coma</span> agité)</td>\n            <td>Antidépresseurs tricycliques ; antipsychotiques ; anti-<span class=\"kw-chiffre\">H1</span> ; <span class=\"kw-ttt\">atropine</span></td>\n            <td><span class=\"kw-clinique\">Mydriase</span> peu réactive ; <span class=\"kw-clinique\">coma agité avec hyperréflexie</span> ; <span class=\"kw-clinique\">hyperthermie</span>, flush ; sécheresse muqueuse ; <span class=\"kw-clinique\">tachycardie</span> ; rétention urinaire</td>\n            <td><span class=\"kw-alerte\">Effet stabilisant de membrane</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Adrénergique</span> / sympathomimétique (<span class=\"kw-clinique\">coma</span> agité)</td>\n            <td>Cocaïne ; amphétamines ; LSD ; xanthines (caféine, théophylline)</td>\n            <td><strong>MATCH :</strong> <span class=\"kw-clinique\">Mydriase</span> · <span class=\"kw-clinique\">Agitation</span> · <span class=\"kw-clinique\">Coma/Convulsions</span> · <span class=\"kw-clinique\">Tachycardie/HyperThermie/HTA</span> · <span class=\"kw-clinique\">Hyperventilation</span></td>\n            <td><span class=\"kw-alerte\">Choc cardiogénique</span> (sidération myocardique)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Sérotoninergique</span></td>\n            <td><span class=\"kw-ttt\">ISRS</span> et autres antidépresseurs ; <span class=\"kw-ttt\">tramadol</span> ; MDMA ; cocaïne</td>\n            <td><span class=\"kw-clinique\">Hyperthermie 40-43 °C</span> ; myoclonies ; <span class=\"kw-clinique\">hyperréflexie</span> ; rigidité, <span class=\"kw-def\">syndrome pyramidal</span> ; mydriase</td>\n            <td><span class=\"kw-alerte\">Choc, CIVD, rhabdomyolyse</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Discriminant pupillaire.</strong> <span class=\"kw-clinique\">Myosis</span> → <span class=\"kw-ttt\">opioïdes</span>, organophosphorés, barbituriques, phénothiazines. <span class=\"kw-clinique\">Mydriase</span> → tricycliques, <span class=\"kw-ttt\">atropine</span>, cocaïne/amphétamines, <span class=\"kw-ttt\">ISRS</span>. La pupille oriente d'emblée la famille du <span class=\"kw-etio\">toxique</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 336 — <span class=\"kw-clinique\">Coma</span> non traumatique · 340 — <span class=\"kw-def\">AVC</span> · 151 — <span class=\"kw-def\">Méningite</span> - <span class=\"kw-clinique\">méningoencéphalite</span></em></p>","frequence":4},{"id":"337-5","rang":"A","rubrique":"Diagnostic positif","titre":"Reconnaître les signes de gravité des intoxications aiguës chez l’adulte","contenu":"<p>L'évaluation de la gravité immédiate est <strong>chronologique et systématique</strong> :</p>\n      <table >\n        <thead><tr><th>Temps</th><th>Gestes</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Premières secondes</strong></td>\n            <td>\n              <strong>Conscience :</strong> <span class=\"kw-def\">score</span> de <span class=\"kw-bio\">Glasgow</span><br>\n              <strong>Ventilation :</strong> <span class=\"kw-bio\">SaO₂</span> ; FR ; encombrement ; obstruction pharyngée<br>\n              <strong>Hémodynamique :</strong> <span class=\"kw-alerte\">arrêt cardiaque</span> ? signes de <span class=\"kw-alerte\">choc</span> ?<br>\n              <strong>Systématique :</strong> <span class=\"kw-bio\">glycémie capillaire</span> ; température\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Quelques minutes</strong></td>\n            <td>Monitorage (SpO₂, scope <span class=\"kw-bio\">ECG</span>, PA) ; <span class=\"kw-ttt\">oxygénothérapie</span> ; position latérale de sécurité + canule de Guedel ; voie veineuse ± remplissage ; appel du sénior/réanimateur</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><span class=\"kw-alerte\">Signes de gravité</span>, par toxidrome :</p>\n      <table >\n        <thead><tr><th>Toxidrome</th><th><span class=\"kw-alerte\">Signe de gravité</span></th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Morphinique</span> / myorelaxant</td><td><span class=\"kw-alerte\">Détresse respiratoire</span></td></tr>\n          <tr><td><span class=\"kw-def\">Anticholinergique</span></td><td><span class=\"kw-alerte\">Coma</span> ; <span class=\"kw-clinique\">rétention aiguë d'urine</span> ; <span class=\"kw-alerte\">effet stabilisant de membrane</span></td></tr>\n          <tr><td><span class=\"kw-def\">Adrénergique</span></td><td><span class=\"kw-alerte\">Choc cardiogénique</span></td></tr>\n          <tr><td><span class=\"kw-def\">Sérotoninergique</span></td><td><span class=\"kw-alerte\">Choc, coma, CIVD, rhabdomyolyse</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span> — évaluation dynamique.</strong> Un <span class=\"kw-alerte\">Glasgow ≤ 8</span> impose la protection des voies aériennes. En toxicologie, l'évaluation des défaillances d'organe est un <strong>processus dynamique à répéter</strong> : il est fréquent qu'un patient arrive conscient puis s'aggrave vers le <span class=\"kw-clinique\">coma</span> au cours de la prise en charge.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span class=\"kw-alerte\">choc</span> · 359 — <span class=\"kw-alerte\">Détresse</span> et <span class=\"kw-ci\">insuffisance respiratoire</span> aiguë</em></p>","frequence":1},{"id":"337-6","rang":"B","rubrique":"Diagnostic positif","titre":"Savoir identifier les autres toxidromes","contenu":"<p>Au-delà des 5 toxidromes principaux, deux entités à savoir identifier :</p>\n      <table >\n        <thead><tr><th>Syndrome cholinergique</th><th>Manifestations</th><th>Toxiques / antidote</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Syndrome nicotinique</span></td>\n            <td>Excitation des muscles striés : <span class=\"kw-clinique\">fasciculations</span>, crampes puis <span class=\"kw-alerte\">paralysies</span> ; troubles respiratoires paralytiques ; <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-def\">HTA</span></td>\n            <td><strong>Toxiques :</strong> nicotine ; organophosphorés<br><strong>Antidote :</strong> <span class=\"kw-ttt\">pralidoxime</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Syndrome muscarinique</span></td>\n            <td>Activation parasympathique — « tous <span class=\"kw-clinique\">les</span> liquides roulent » : <span class=\"kw-clinique\">hypersalivation</span>, larmoiement, <span class=\"kw-clinique\">sueurs</span>, bronchorrhée, <span class=\"kw-clinique\">diarrhée</span>, <span class=\"kw-clinique\">vomissements</span> ; <span class=\"kw-clinique\">bradycardie</span>, <span class=\"kw-clinique\">hypotension</span> ; <span class=\"kw-clinique\">myosis</span> ; bronchoconstriction</td>\n            <td><strong>Toxiques :</strong> anticholinestérasiques ; organophosphorés ; champignons<br><strong>Antidote :</strong> <span class=\"kw-ttt\">atropine</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Syndrome malin des neuroleptiques.</strong> Début rapidement progressif : <span class=\"kw-clinique\">hyperthermie</span> (<span class=\"kw-chiffre\">40-41 °C</span>) ou <span class=\"kw-clinique\">hypothermie</span> ; <span class=\"kw-clinique\">rigidité extrapyramidale</span> ; dysautonomie ; troubles de la vigilance. Biologie : hyperleucocytose à PNN, <span class=\"kw-bio\">CPK / LDH élevées</span>. Traitement : transfert en <span class=\"kw-alerte\">réanimation</span>, arrêt du neuroleptique (<span class=\"kw-ci\">contre-indiqué</span> à vie), <span class=\"kw-ttt\">bromocriptine</span> ou <span class=\"kw-ttt\">dantrolène</span>.\n      </div>","frequence":1},{"id":"337-7","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir suspecter un évènement chimique de grande ampleur","contenu":"<p><span class=\"kw-clinique\">Les</span> substances toxiques peuvent être utilisées comme <span class=\"kw-etio\">arme militaire ou terroriste</span>, ou être libérées lors d'un <span class=\"kw-etio\">accident industriel</span>.</p>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-def\">Critère de</span> suspicion.</strong> Une intoxication de grande ampleur doit être suspectée lorsque <strong>plusieurs personnes provenant du même endroit se présentent avec <span class=\"kw-clinique\">les</span> mêmes symptômes</strong>.\n      </div>\n      <p><span class=\"kw-clinique\">Les</span> substances impliquées sont nombreuses : <span class=\"kw-etio\">neurotoxiques</span> ; <span class=\"kw-etio\">irritants des voies respiratoires</span> (pouvant aller jusqu'au <span class=\"kw-alerte\">SDRA</span>) ; <span class=\"kw-etio\">asphyxiants</span>. Reconnaître la situation impose un changement complet de logique : il ne s'agit plus d'abord de soigner, mais d'anticiper et de se protéger (cf. obj-19).</p>","frequence":0},{"id":"337-8","rang":"B","rubrique":"Examens complémentaires","titre":"Savoir identifier un effet stabilisant de membrane","contenu":"<p>L'<span class=\"kw-def\">effet stabilisant de membrane</span> (ESM) = <strong>blocage des canaux sodiques cardiaques</strong> → altération électrophysiologique des membranes (augmentation de l'excitabilité, diminution de la conduction, de l'inotropisme et de l'automaticité). La recherche de cet effet motive l'<strong>indication très large de l'<span class=\"kw-bio\">ECG</span></strong> dans <span class=\"kw-clinique\">les</span> intoxications.</p>\n      <table >\n        <thead><tr><th>Élément</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Signe d'alerte</strong></td>\n            <td>Blocage des canaux potassiques (précède le blocage sodique) → <span class=\"kw-imagerie\">allongement modéré du QT</span> — ce n'est <strong>qu'un signe d'alerte</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Signes <span class=\"kw-bio\">ECG</span></strong></td>\n            <td><span class=\"kw-imagerie\">Aplatissement de l'onde T</span> ; allongement du <span class=\"kw-imagerie\">QT</span> ; allongement du <span class=\"kw-imagerie\">PR</span> ; <span class=\"kw-alerte\">élargissement du QRS &gt; 120 ms</span> ; <span class=\"kw-alerte\">arythmies ventriculaires</span></td>\n          </tr>\n          <tr>\n            <td><strong>Toxiques en cause</strong></td>\n            <td>\n              <strong>Anti-arythmiques :</strong> <span class=\"kw-chiffre\">classe I</span> de Vaughan-Williams (<span class=\"kw-ttt\">flécaïnide</span>, quinidine, <span class=\"kw-ttt\">lidocaïne</span>)<br>\n              <strong>Cardiotropes :</strong> <span class=\"kw-ttt\">β-bloquants</span> (<span class=\"kw-ttt\">propranolol</span> ++) ; anticalciques bradycardisants<br>\n              <strong>Psychotropes :</strong> <span class=\"kw-ttt\">antidépresseurs tricycliques</span> ; phénothiazines ; carbamazépine<br>\n              <strong>Autres :</strong> quinine, chloroquine ; cocaïne\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>Conduite à tenir.</strong> Le <span class=\"kw-ttt\">bicarbonate de sodium molaire (8,4 %)</span> est l'antidote, à administrer <strong>uniquement lorsque <span class=\"kw-clinique\">les</span> QRS sont élargis</strong> (l'allongement du QT seul ne justifie pas le traitement). En cas d'échec : assistance circulatoire (ECMO) à discuter avec un centre expert.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 234 — <span class=\"kw-def\">Insuffisance cardiaque</span></em></p>","frequence":0},{"id":"337-9","rang":"B","rubrique":"Examens complémentaires","titre":"Savoir quand et comment demander un bilan biologique toxicologique","contenu":"<p>Le bilan se gradue selon la présentation. <strong>Le dosage des toxiques n'est pas nécessaire lorsque <span class=\"kw-clinique\">les</span> substances ingérées sont clairement identifiées</strong> (témoin, aveu du patient).</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Bilan</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Systématique</strong></td>\n            <td><span class=\"kw-bio\">ECG</span> (recherche d'un effet stabilisant de membrane) ; <span class=\"kw-bio\">glycémie capillaire</span> répétée</td>\n          </tr>\n          <tr>\n            <td><strong>Symptomatique</strong> (<span class=\"kw-def\">Glasgow</span> &lt; 14)</td>\n            <td>\n              <strong>Non spécifique :</strong> <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">créatinine</span>, <span class=\"kw-bio\">urée</span><br>\n              <strong>Ciblé :</strong> <span class=\"kw-bio\">bilan hépatique</span> + <span class=\"kw-bio\">TP</span> si <span class=\"kw-ttt\">paracétamol</span> ; <span class=\"kw-imagerie\"><span class=\"kw-imagerie\">échographie</span> cardiaque</span> + <span class=\"kw-bio\">lactate</span> si cardiotrope ; <span class=\"kw-bio\">gaz du sang</span> + <span class=\"kw-imagerie\">RXT</span> si atteinte respiratoire\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Asymptomatique, <span class=\"kw-etio\">toxique</span> fonctionnel</strong> à <span class=\"kw-alerte\">risque vital</span> faible</td>\n            <td>Pas de bilan requis (peut se discuter selon <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">comorbidités</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Asymptomatique, <span class=\"kw-etio\">toxique</span> lésionnel</strong></td>\n            <td>Bilan de l'organe cible : <span class=\"kw-ttt\">lithium</span> → rein ; <span class=\"kw-ttt\">paracétamol</span> → foie</td>\n          </tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Examen toxicologique</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Dosage spécifique</strong></td>\n            <td>Toxiques dont la toxicité dépend de la concentration et accessibles à un traitement spécifique — <strong><span class=\"kw-ttt\">paracétamol</span> en premier lieu</strong> ; résultat rendu en &lt;<span class=\"kw-chiffre\"> 2 h</span></td>\n          </tr>\n          <tr>\n            <td><strong>Criblage toxicologique</strong></td>\n            <td>Absence d'orientation sur <span class=\"kw-clinique\">les</span> produits ingérés ; ou doute chez un patient avec <span class=\"kw-alerte\">signes de gravité</span> (hors <span class=\"kw-clinique\">coma</span> expliqué par un <span class=\"kw-etio\">toxique</span> fonctionnel)</td>\n          </tr>\n          <tr>\n            <td><strong>Prélèvement conservatoire</strong></td>\n            <td><span class=\"kw-chiffre\">≥ 2</span> tubes de sérum + 1 tube d'urine conservés au réfrigérateur ; envoyés au laboratoire seulement si <span class=\"kw-clinique\">évolution</span> défavorable ou nouvelle information</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Imagerie.</strong> <span class=\"kw-imagerie\">RXT</span> si suspicion de complication respiratoire (<span class=\"kw-clinique\">pneumopathie d'inhalation</span>). <span class=\"kw-imagerie\">TDM cérébrale</span> si trouble de la vigilance non expliqué par le <span class=\"kw-etio\">toxique</span>, signe de focalisation, ou suspicion de traumatisme crânien passé inaperçu.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 267 — Trouble de l’équilibre acido-basique - Désordre hydro-électrolytique</em></p>","frequence":0},{"id":"337-10","rang":"A","rubrique":"Prise en charge","titre":"Savoir mettre en œuvre le traitement symptomatique à la phase initiale","contenu":"<p>Le traitement symptomatique est <strong>guidé par la présence d'une <span class=\"kw-alerte\">défaillance</span> d'organe</strong>, sans spécificité toxicologique. Il prime sur le traitement spécifique.</p>\n      <table >\n        <thead><tr><th>Défaillance</th><th>Traitement symptomatique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Neurologique</strong></td>\n            <td><span class=\"kw-alerte\">Protection des voies aériennes</span> par <span class=\"kw-ttt\">intubation</span>-ventilation si <span class=\"kw-alerte\">Glasgow &lt; 8</span> non réversible par antidote</td>\n          </tr>\n          <tr>\n            <td><strong>Respiratoire</strong></td>\n            <td>Prise en charge d'une <span class=\"kw-clinique\">pneumopathie d'inhalation</span></td>\n          </tr>\n          <tr>\n            <td><strong>Hémodynamique</strong></td>\n            <td><span class=\"kw-clinique\">État de choc</span> : <strong>remplissage initial</strong> (sauf <span class=\"kw-def\">OAP</span> manifeste), puis catécholamine si insuffisant — typiquement <span class=\"kw-ttt\">noradrénaline</span> (effets α vasoconstricteurs + β inotropes)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Choc cardiogénique</span> / <span class=\"kw-alerte\">ACR</span> réfractaire</strong></td>\n            <td><span class=\"kw-ttt\">ECMO veino-artérielle</span> — <strong>indication formelle</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Rénale / métabolique</strong></td>\n            <td><span class=\"kw-ttt\">Épuration extrarénale</span> si <span class=\"kw-ci\">insuffisance rénale</span> ou trouble métabolique grave</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span class=\"kw-alerte\">choc</span> · 359 — <span class=\"kw-alerte\">Détresse</span> et <span class=\"kw-ci\">insuffisance respiratoire</span> aiguë</em></p>","frequence":2},{"id":"337-11","rang":"B","rubrique":"Prise en charge","titre":"Connaître le traitement spécifique d’une intoxication aux morphiniques","contenu":"<p>L'antidote du toxidrome morphinique est la <span class=\"kw-ttt\">naloxone</span> (Narcan®), <strong>antagoniste des récepteurs morphiniques μ</strong>. Son administration titrée est un attendu EDN détaillé.</p>\n      <p>Avant l'antidote, on évalue la sédation et la respiration :</p>\n      <table >\n        <thead><tr><th>Échelle de sédation (EDS)</th><th>Échelle de qualité de la respiration (EQR)</th></tr></thead>\n        <tbody>\n          <tr><td>EDS 0 : éveillé</td><td>R0 : respiration normale, FR <span class=\"kw-chiffre\">≥ 10/min</span></td></tr>\n          <tr><td>EDS 1 : somnolent, facilement éveillable</td><td>R1 : ronflements, FR &gt;<span class=\"kw-chiffre\"> 10/min</span></td></tr>\n          <tr><td>EDS 2 : éveillable par stimulation verbale</td><td>R2 : respiration irrégulière ou FR &lt;<span class=\"kw-chiffre\"> 10/min</span></td></tr>\n          <tr><td>EDS 3 : éveillable par stimulation tactile</td><td>R3 : pauses ou apnée</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Modalité</th><th>Naloxone</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Objectif</strong></td>\n            <td>Surseoir à l'<span class=\"kw-ttt\">intubation</span> tout en évitant un <span class=\"kw-clinique\">syndrome de sevrage</span> — <strong>amélioration de la conscience, pas le réveil complet</strong> ; cible <span class=\"kw-chiffre\">FR &gt; 15/min</span></td>\n          </tr>\n          <tr>\n            <td><strong>Titration</strong></td>\n            <td>Bolus IV de <span class=\"kw-chiffre\">0,04 à 0,08 mg</span> toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2 minutes</span>, jusqu'à <span class=\"kw-chiffre\">2 mg maximum</span> ; si arrêt respiratoire : <span class=\"kw-chiffre\">0,2 mg</span> toutes les <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span> min</span>utes</td>\n          </tr>\n          <tr>\n            <td><strong>Entretien</strong></td>\n            <td>Si objectif atteint : perfusion continue sur <span class=\"kw-chiffre\">4 h</span> (dose horaire = moitié de la dose de titration) — justifiée car la durée d'action de la <span class=\"kw-ttt\">naloxone</span> est plus courte que celle des <span class=\"kw-ttt\">opioïdes</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ci\">Contre-indication</span></strong></td>\n            <td>Aucune ; existe en <span class=\"kw-ttt\">spray nasal</span> et en IM (utilisable par <span class=\"kw-clinique\">les</span> secouristes et l'entourage)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Si échec de la <span class=\"kw-ttt\">naloxone</span>.</strong> Faire revoir le diagnostic d'intoxication isolée aux <span class=\"kw-ttt\">opioïdes</span>, ou évoquer la <span class=\"kw-ttt\">buprénorphine</span> (<span class=\"kw-def\">dépression</span> respiratoire non réversible par la <span class=\"kw-ttt\">naloxone</span> aux doses usuelles).\n      </div>","frequence":2},{"id":"337-12","rang":"B","rubrique":"Prise en charge","titre":"Connaître le traitement spécifique d’une intoxication aux benzodiazépines (et hypnotiques apparentés)","contenu":"<p>L'antidote est le <span class=\"kw-ttt\">flumazénil</span> (Anexate®), <strong>antagoniste des récepteurs GABAergiques</strong>.</p>\n      <table >\n        <thead><tr><th>Modalité</th><th>Flumazénil</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Objectif</strong></td>\n            <td>Réveil suffisant pour la <strong>protection des voies aériennes</strong> et <strong>éviter l'<span class=\"kw-ttt\">intubation</span></strong> — <strong>pas le réveil complet</strong> (qui exposerait à l'agitation, la violence, la fugue)</td>\n          </tr>\n          <tr>\n            <td><strong>Titration</strong></td>\n            <td>Bolus IV de <span class=\"kw-chiffre\">0,2 mg</span>, puis <span class=\"kw-chiffre\">0,1 mg</span> toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2 minutes</span>, jusqu'à <span class=\"kw-chiffre\">2 mg maximum</span> ; perfusion continue ensuite si objectif atteint</td>\n          </tr>\n          <tr>\n            <td><strong>Effets indésirables</strong></td>\n            <td>Syndrome de <span class=\"kw-ttt\">sevrage</span> aux <span class=\"kw-ttt\">benzodiazépines</span> si surdosage ; risque d'inhalation au réveil chez le sujet âgé</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-ci\">Contre-indications</span> du flumazénil.</strong> <span class=\"kw-ci\">Épilepsie</span> connue ou constatée ; <span class=\"kw-ci\">poly-intoxication sévère</span> ; suspicion de <span class=\"kw-ci\">molécules proconvulsivantes</span> (notamment <strong>atypies évoquant un syndrome atropinique</strong> — tricycliques). Risque de <span class=\"kw-alerte\">convulsions</span> par levée de l'effet anticonvulsivant des <span class=\"kw-ttt\">benzodiazépines</span>. Si le diagnostic n'est pas certain, ne pas administrer.\n      </div>","frequence":1},{"id":"337-13","rang":"A","rubrique":"Prise en charge","titre":"Savoir demander un avis psychiatrique systématique en cas d’intoxication volontaire","contenu":"<p><strong>Tout patient hospitalisé pour une intoxication médicamenteuse volontaire doit bénéficier d'une évaluation psychiatrique</strong> (ou addictologique si contexte de toxicomanie) <strong>avant la sortie</strong> — obl<span class=\"kw-chiffre\">iga</span>tion médico-légale.</p>\n      <table >\n        <thead><tr><th>Item</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Objectifs de l'évaluation</strong></td>\n            <td>Évaluer l'<span class=\"kw-clinique\">intentionnalité suicidaire</span> ; le <span class=\"kw-alerte\">risque de récidive immédiat</span> ; la disponibilité de l'entourage ; l'adhésion aux soins</td>\n          </tr>\n          <tr>\n            <td><strong>Orientation</strong></td>\n            <td>Consultation en centre médico-psychologique <strong>dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">48 h</span></strong> après la sortie ; ou <span class=\"kw-alerte\">hospitalisation</span> complète, avec ou sans consentement</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Hospitalisation</span> systématique.</strong> Une hospitalisation est indiquée devant <strong>toute intoxication volontaire</strong>, <span class=\"kw-alerte\">même en l'absence de signe de gravité</span> — en raison du risque élevé d'aggravation secondaire et de récidive dans un contexte psychiatrique.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 353 — Risque et conduite suicidaire</em></p>","frequence":1},{"id":"337-14","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement d’une intoxication aiguë au paracétamol chez l’adulte et l’enfant","contenu":"<p>Le <span class=\"kw-def\">paracétamol</span> est le <strong><span class=\"kw-etio\">toxique</span> lésionnel le plus typique et le plus fréquent</strong>. Métabolisé à <span class=\"kw-chiffre\">90 %</span> par le foie en dérivés conjugués non toxiques, et à <span class=\"kw-chiffre\">10 %</span> par le <span class=\"kw-bio\">cytochrome P450</span> en <span class=\"kw-alerte\">NAPQI</span> hépatotoxique — normalement inactivé par le <span class=\"kw-bio\">glutathion</span>. En cas de dose toxique ou de réserves de glutathion épuisées (<span class=\"kw-etio\">alcoolisme</span>, dénutrition, inducteurs enzymatiques), le NAPQI s'accumule → <span class=\"kw-alerte\">nécrose hépatique centrolobulaire</span>.</p>\n      <table >\n        <thead><tr><th>Élément</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Dose <span class=\"kw-etio\">toxique</span></strong> (ingestion unique)</td>\n            <td>Enfant &lt;<span class=\"kw-chiffre\"> 6 ans</span> : <span class=\"kw-chiffre\">&gt; 200 mg/kg</span> ; enfant <span class=\"kw-chiffre\">≥ 6 ans</span> et adulte : <span class=\"kw-chiffre\">&gt; 150 mg/kg</span></td>\n          </tr>\n          <tr>\n            <td><strong>Antidote</strong></td>\n            <td><span class=\"kw-ttt\">N-acétylcystéine</span> (NAC) — régénère le glutathion ; voie orale (<span class=\"kw-chiffre\">72 h</span>) ou IV (<span class=\"kw-chiffre\">48 h</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Nomogramme de Rumack-Matthew</strong></td>\n            <td>Paracétamolémie interprétable <strong>à partir de H4</strong> post-ingestion ; efficacité maximale de la NAC si débutée &lt;<span class=\"kw-chiffre\"> 8-10 h</span>, et impérativement <strong>avant <span class=\"kw-chiffre\">H12</span></strong></td>\n          </tr>\n          <tr>\n            <td><strong>Indications NAC chez l'enfant</strong></td>\n            <td>Dès l'arrivée si forte suspicion, signes de toxicité, ingestion &gt;<span class=\"kw-chiffre\"> 8 h</span>, dose &gt;<span class=\"kw-chiffre\"> 150 mg/kg</span> ou poly-intoxication ; sinon après H4 selon la paracétamolémie</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-alerte\"><span class=\"kw-def\">Critères de</span> gravité</span> <span class=\"kw-ttt\">biologique</span>.</strong> Ce sont le <span class=\"kw-bio\">TP</span>, le <span class=\"kw-bio\">facteur V</span> et la <span class=\"kw-bio\">bilirubinémie</span> (fonction hépatique de synthèse). <span class=\"kw-alerte\">Les transaminases et la cholestase ne sont PAS des critères de gravité.</span> Une <span class=\"kw-def\">hépatite</span> fulminante impose le <span class=\"kw-def\">contact</span> avec un centre de transplantation hépatique.\n      </div>","frequence":2},{"id":"337-15","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement d’une intoxication aiguë aux autres psychotropes","contenu":"<p>Au-delà des <span class=\"kw-ttt\">benzodiazépines</span> (obj-11) et des morphiniques (obj-10), trois familles de psychotropes à connaître. Aucune ne dispose d'antidote spécifique — le traitement est avant tout symptomatique.</p>\n      <table >\n        <thead><tr><th>Psychotrope</th><th>Risques</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-ttt\">Antidépresseurs tricycliques</span> (amitriptyline, clomipramine)</td>\n            <td>Toxidrome <span class=\"kw-alerte\">anticholinergique</span> + <span class=\"kw-alerte\">sérotoninergique</span> + <span class=\"kw-alerte\">effet stabilisant de membrane</span></td>\n            <td><strong>Pas d'antidote</strong>, non dialysable ; charbon activé si dose importante et prise en charge &lt;<span class=\"kw-chiffre\"> 1 h</span> ; <span class=\"kw-bio\">bicarbonate</span> molaire si QRS &gt; 120 ms</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Neuroleptiques</span></td>\n            <td><span class=\"kw-alerte\">Syndrome malin des neuroleptiques</span> ; phénothiazines : anticholinergique + ESM ; nouvelle génération : <span class=\"kw-clinique\">coma calme hypotonique</span></td>\n            <td>Pas d'antidote ; symptomatique ; <span class=\"kw-ttt\">bromocriptine</span> ou <span class=\"kw-ttt\">dantrolène</span> pour le syndrome malin</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Lithium</span></td>\n            <td><span class=\"kw-etio\">Toxique</span> lésionnel ; syndrome <span class=\"kw-clinique\">cérébelleux</span>, myoclonies, <span class=\"kw-clinique\">convulsions</span> ; troubles de conduction (BAV) ; <span class=\"kw-alerte\">IRA fonctionnelle</span></td>\n            <td>Pas d'antidote ; <strong>non carbo-adsorbable</strong> (pas de charbon) ; lavage gastrique si prise massive &lt;<span class=\"kw-chiffre\"> 1 h</span> ; <span class=\"kw-ttt\">hémodialyse</span> si retentissement sévère (surveiller le rebond post-dialyse)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-ttt\">ISRS</span>.</strong> L'intoxication aux inhibiteurs sélectifs de la recapture de la sérotonine expose au <span class=\"kw-alerte\">syndrome sérotoninergique</span> : traitement symptomatique (rééquilibration hydro-électrolytique, lutte contre l'<span class=\"kw-clinique\">hyperthermie</span>), arrêt du médicament, transfert en <span class=\"kw-alerte\">réanimation</span> si forme grave.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 74 — Psychotropes</em></p>","frequence":0},{"id":"337-16","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement d’une intoxication aiguë aux cardiotropes","contenu":"<p>L'intoxication aux cardiotropes nécessite une <strong><span class=\"kw-def\">surveillance</span> scopée en unité de <span class=\"kw-alerte\">soins intensifs</span> ou de réanimation</strong>, avec monitorage hémodynamique précis.</p>\n      <table >\n        <thead><tr><th>Mesure commune</th><th>Modalité</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">Décontamination</span> digestive</strong></td><td>Charbon activé ou lavage gastrique si prise importante et précoce (&lt;<span class=\"kw-chiffre\"> 1 h</span>)</td></tr>\n          <tr><td><strong>Hémodynamique</strong></td><td>Remplissage (cristalloïdes <span class=\"kw-chiffre\">500-1000 mL</span>) si PAS &lt;<span class=\"kw-chiffre\"> 100 mmHg</span> ; <span class=\"kw-ttt\">catécholamines</span> (<span class=\"kw-ttt\">adrénaline</span>, <span class=\"kw-ttt\">noradrénaline</span>, <span class=\"kw-ttt\">dobutamine</span>)</td></tr>\n          <tr><td><strong>Si QRS &gt; 120 ms</strong></td><td><span class=\"kw-ttt\">Bicarbonate de sodium molaire 8,4 %</span> (<span class=\"kw-def\">surveillance</span> de la <span class=\"kw-bio\">kaliémie</span>)</td></tr>\n          <tr><td><strong>Si FC &lt;<span class=\"kw-chiffre\"> 50 bpm</span></strong></td><td><span class=\"kw-ttt\">Atropine</span> en bolus ; entraînement électrosystolique externe en attente</td></tr>\n          <tr><td><strong>Dernier recours</strong></td><td>Assistance circulatoire (ECMO) si <span class=\"kw-def\">choc cardiogénique</span> réfractaire ou <span class=\"kw-alerte\">arrêt cardiaque</span></td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Traitement spécifique</th><th>Molécule</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-ttt\">Digitaliques</span></td>\n            <td><strong><span class=\"kw-bio\">Anticorps anti-digoxine</span> (fragments Fab).</strong> Arrêt de tout digitalique et de tout médicament hyperkaliémiant ; <span class=\"kw-ci\">contre-indication aux catécholamines</span> ; <span class=\"kw-ci\">contre-indication au gluconate de calcium</span> pour traiter l'hyperkaliémie ; <span class=\"kw-ttt\">CEE</span> <span class=\"kw-ci\">contre-indiqué</span> sauf <span class=\"kw-alerte\">FV</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Inhibiteurs calciques</span></td>\n            <td>Catécholamines (<span class=\"kw-ttt\">noradrénaline</span>, <span class=\"kw-ttt\">dobutamine</span>) ; si forme grave : <span class=\"kw-ttt\">sels de calcium</span> + <span class=\"kw-ttt\">insuline euglycémique</span> (<span class=\"kw-ttt\">insuline</span> à fortes doses + glucose) ; <span class=\"kw-ttt\">glucagon</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">β-bloquants</span></td>\n            <td>Antagonisme par <span class=\"kw-clinique\">les</span> catécholamines (isoprénaline, <span class=\"kw-ttt\">dobutamine</span>, <span class=\"kw-ttt\">noradrénaline</span>) ; antidote possible : <span class=\"kw-ttt\">glucagon</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-ci\">Contre-indication</span>.</strong> L'intoxication aux cardiotropes <span class=\"kw-ci\">contre-indique l'utilisation des anti-arythmiques</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 234 — <span class=\"kw-def\">Insuffisance cardiaque</span> · 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":0},{"id":"337-17","rang":"A","rubrique":"Prise en charge","titre":"Savoir diagnostiquer une intoxication aiguë au monoxyde de carbone et connaître les principes de prise en charge chez l’adulte et l’enfant","contenu":"<p><strong>Objectif EDN majeur (4 ⭐).</strong> Le <span class=\"kw-def\">monoxyde de carbone</span> est un gaz <strong>inodore, incolore, insipide et non irritant</strong>, produit par toute combustion incomplète (chaudières, incendies, gaz d'échappement) — surtout en <strong>lieu clos</strong>. Environ <span class=\"kw-chiffre\">8000 cas/an</span> en France, dont <span class=\"kw-chiffre\">20 % d'enfants</span> : <strong>1<sup>re</sup> cause de décès par intoxication</strong>.</p>\n      <p><strong><span class=\"kw-def\">Physiopathologie</span>.</strong> L'affinité du CO pour l'<span class=\"kw-bio\">hémoglobine</span> est <span class=\"kw-chiffre\">230 fois</span> supérieure à celle de l'O₂ → formation de <span class=\"kw-bio\">carboxyhémoglobine (HbCO)</span> et <span class=\"kw-alerte\">hypoxie cellulaire</span> (<span class=\"kw-clinique\">les</span> chaînes respiratoires mitochondriales sont aussi inhibées). Le CO passe la barrière placentaire → <span class=\"kw-alerte\">toxicité fœtale</span>. Organes cibles : cerveau et myocarde.</p>\n      <table >\n        <thead><tr><th>Présentation</th><th>Signes</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Formes bénignes</strong></td>\n            <td><span class=\"kw-clinique\">Céphalées</span> (<span class=\"kw-chiffre\">90 %</span>), évocatrices si <strong>nocturnes / disparaissant le matin</strong> ou survenant dans une pièce précise ; <span class=\"kw-clinique\">asthénie</span>, <span class=\"kw-clinique\">nausées</span>, <span class=\"kw-clinique\">vertiges</span>, sensation ébrieuse</td>\n          </tr>\n          <tr>\n            <td><strong>Formes graves</strong></td>\n            <td><span class=\"kw-alerte\">Coma hypertonique</span> avec irritation pyramidale, comitialité ; <span class=\"kw-imagerie\">anomalies ECG</span> (troubles du rythme, ischémie) ; collapsus, <span class=\"kw-clinique\">œdème</span> pulmonaire</td>\n          </tr>\n          <tr>\n            <td><strong>Peau</strong></td>\n            <td><span class=\"kw-clinique\">Teinte cochenille</span> des téguments (intoxication massive)</td>\n          </tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/337/co-teinte-cochenille.png\" alt=\"Coloration cochenille des téguments lors d'une intoxication massive au monoxyde de carbone\" loading=\"lazy\">\n        <figcaption>Coloration « cochenille » des téguments — signe cutané de l'intoxication massive au CO. Source : fiche source EDN item 337 (Intoxication au monoxyde de carbone).</figcaption>\n      </figure>\n      <table >\n        <thead><tr><th>HbCO — seuils diagnostiques</th><th>Asymptomatique</th><th>Symptomatique</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Fumeur</strong></td><td><span class=\"kw-chiffre\">≥ 10 %</span></td><td><span class=\"kw-chiffre\">≥ 6 %</span></td></tr>\n          <tr><td><strong>Non-fumeur</strong></td><td><span class=\"kw-chiffre\">≥ 6 %</span></td><td><span class=\"kw-chiffre\">≥ 3 %</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>Pièges diagnostiques.</strong> La <span class=\"kw-bio\">SpO₂ et la SaO₂ sont faussement rassurantes</span> (<span class=\"kw-clinique\">les</span> appareils mesurent l'HbCO comme de l'HbO₂). Des <span class=\"kw-bio\">gaz du sang</span> normaux <span class=\"kw-alerte\">n'éliminent pas le diagnostic</span> — seule une valeur d'HbCO anormale a un intérêt. Un taux d'HbCO &gt;<span class=\"kw-chiffre\"> 30 %</span> aboutit au <span class=\"kw-clinique\">coma</span>.\n      </div>\n      <table >\n        <thead><tr><th>Prise en charge</th><th>Modalité</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Éviction</strong></td>\n            <td>Aération des locaux, arrêt de la source, évacuation de la zone contaminée</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Oxygénothérapie</span> normobare</strong></td>\n            <td><span class=\"kw-ttt\">O₂ pur au masque haute concentration 15 L/min</span>, débuté en préhospitalier, poursuivi <span class=\"kw-chiffre\">≥ 12 h</span> (demi-vie du CO :<span class=\"kw-chiffre\"> 30-40 min</span> sous O₂ contre <span class=\"kw-chiffre\">3-4 h</span> en <span class=\"kw-def\">air</span> ambiant)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Oxygénothérapie</span> hyperbare</strong></td>\n            <td>Indiquée dans <span class=\"kw-clinique\">les</span> formes graves : signes neurologiques (perte de connaissance, irritation pyramidale) ; <span class=\"kw-alerte\">ischémie myocardique</span> ; <span class=\"kw-chiffre\">HbCO &gt; 25 %</span> ; <strong>femme enceinte (systématique)</strong> ; enfant (indications larges)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-def\">Suivi</span>.</strong> <span class=\"kw-def\">Signalement</span> obl<span class=\"kw-chiffre\">iga</span>toire à l'ARS via le centre antipoison. Consultation de contrôle à<span class=\"kw-chiffre\"> 1 mois</span> (<span class=\"kw-def\">dépistage</span> de séquelles). Le <span class=\"kw-alerte\">syndrome post-intervallaire</span> apparaît vers <span class=\"kw-chiffre\">3 semaines</span> (entre 2 et <span class=\"kw-chiffre\">40 jours</span>) : troubles mnésiques, du comportement, <span class=\"kw-clinique\">céphalées</span> chroniques, démence précoce, crises convulsives.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë</em></p>","frequence":4},{"id":"337-18","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge d’une intoxication alcoolique aiguë","contenu":"<p>L'<span class=\"kw-etio\">éthanol</span> est un <span class=\"kw-etio\">toxique</span> fonctionnel responsable d'un <span class=\"kw-def\">toxidrome de myorelaxation</span> : <span class=\"kw-clinique\">coma calme hypotonique</span>, <span class=\"kw-clinique\">hyporéflexie</span>, <span class=\"kw-clinique\">dysarthrie</span>, <span class=\"kw-clinique\">bradypnée</span>. C'est une co-intoxication <strong>très fréquente</strong> (associée à plus de <span class=\"kw-chiffre\">40 %</span> des intoxications médicamenteuses).</p>\n      <table >\n        <thead><tr><th>Élément</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Risques</strong></td>\n            <td><span class=\"kw-alerte\">Hypothermie</span> (action centrale de l'<span class=\"kw-etio\">alcool</span> sur la thermorégulation + exposition au froid) ; obstruction des voies aériennes ; inhalation</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Diagnostic différentiel</span> à éliminer</strong></td>\n            <td><span class=\"kw-alerte\">Traumatisme crânien</span> passé inaperçu — <span class=\"kw-imagerie\">TDM cérébrale</span> si trouble de la vigilance non expliqué par l'alcoolémie</td>\n          </tr>\n          <tr>\n            <td><strong>Traitement symptomatique</strong></td>\n            <td>Protection des voies aériennes ; <span class=\"kw-def\">surveillance</span> de la conscience, de la <span class=\"kw-bio\">glycémie</span> et de la température ; réchauffement ; hydratation</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> <span class=\"kw-clinique\">Les</span> fiches sources du dossier <code>337-intoxications-aigue/</code> décrivent l'<span class=\"kw-etio\">alcool</span> comme toxidrome de myorelaxation mais ne détaillent pas la prise en charge spécifique de l'intoxication alcoolique aiguë (vitaminothérapie B1, seuils d'alcoolémie, modalités de <span class=\"kw-def\">surveillance</span>). À enrichir depuis le Collège / Pilly.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 76 — Addiction à l’<span class=\"kw-etio\">alcool</span> · 340 — <span class=\"kw-def\">AVC</span></em></p>","frequence":0},{"id":"337-19","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge d’une intoxication aiguë aux fumées d’incendie","contenu":"<p>L'intoxication aux <span class=\"kw-etio\">fumées d'incendie</span> associe une <strong>double intoxication</strong> : <span class=\"kw-etio\">monoxyde de carbone</span> (cf. obj-16) et <span class=\"kw-etio\">cyanure</span>.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-etio\">Toxique</span></th><th>Mécanisme et traitement</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Monoxyde de carbone</span></td>\n            <td>Hypoxie par carboxyhémoglobine ; <strong><span class=\"kw-ttt\">oxygénothérapie</span></strong> normobare ± hyperbare (cf. obj-16)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Cyanure</span></td>\n            <td>\n              <strong>Mécanisme :</strong> l'ion cyanure inhibe la <span class=\"kw-bio\">cytochrome oxydase</span> mitochondriale → métabolisme <span class=\"kw-etio\">anaérobie</span> → <span class=\"kw-alerte\">hypoxie cellulaire sans hypoxémie</span><br>\n              <strong>Clinique :</strong> troubles de conscience ; <span class=\"kw-clinique\">céphalées</span> ; <span class=\"kw-clinique\">douleur thoracique</span> (tableau de <span class=\"kw-def\">SCA</span> possible) ; <span class=\"kw-clinique\">convulsions</span> ; collapsus ; odeur d'amande amère<br>\n              <strong>Biologie :</strong> <span class=\"kw-bio\">acidose métabolique</span> avec <span class=\"kw-bio\">hyperlactatémie</span> (&gt;<span class=\"kw-chiffre\"> 8-10 mmol/L</span>)<br>\n              <strong>Antidote :</strong> <span class=\"kw-ttt\">hydroxocobalamine</span> (Cyanokit® — <span class=\"kw-bio\">vitamine B12</span>), si gravité clinique + hyperlactatémie &gt;<span class=\"kw-chiffre\"> 10 mmol/L</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> La coloration rouge carmin des urines après hydroxocobalamine témoigne de son excrétion — elle est <strong>normale, non pathologique</strong>. Risque de l'antidote : <span class=\"kw-alerte\">néphropathie aiguë</span> par précipitation de cristaux d'oxalate — d'où une administration réservée aux patients avec <span class=\"kw-alerte\">signes de gravité</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 359 — <span class=\"kw-alerte\">Détresse</span> et <span class=\"kw-ci\">insuffisance respiratoire</span> aiguë</em></p>","frequence":0},{"id":"337-20","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de protection en cas d’évènement chimique de grande ampleur","contenu":"<p>Lors d'une intoxication de grande ampleur, <strong>la logique change complètement</strong> : le problème n'est pas de soigner mais d'<strong>anticiper, se protéger, protéger <span class=\"kw-clinique\">les</span> lieux de soins et les soignants</strong> — afin de préserver la capacité de l'hôpital à remplir sa mission. Lors des dernières intoxications massives, les victimes ont fréquemment été les membres du personnel médical.</p>\n      <table >\n        <thead><tr><th>Mesure</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Sur <span class=\"kw-clinique\">les</span> lieux de l'accident</strong></td>\n            <td>L'urgent est de <span class=\"kw-alerte\">fuir la zone</span>, puis d'appeler <span class=\"kw-clinique\">les</span> secours</td>\n          </tr>\n          <tr>\n            <td><strong>À l'hôpital</strong></td>\n            <td>L'urgent est de <span class=\"kw-alerte\">fermer les portes des urgences</span> pour éviter l'entrée non contrôlée des victimes contaminées</td>\n          </tr>\n          <tr>\n            <td><strong>Organisation</strong></td>\n            <td>Mise en place d'un <span class=\"kw-clinique\">périmètre de sécurité</span> ; d'une <span class=\"kw-clinique\">chaîne de décontamination</span> ; réorganisation des urgences et de tout l'hôpital</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>Principe directeur.</strong> Protéger <span class=\"kw-clinique\">les</span> lieux de soins et les soignants prime sur le soin immédiat : un soignant contaminé devient une victime supplémentaire et ampute la capacité de réponse.\n      </div>","frequence":0},{"id":"337-21","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications d’une décontamination digestive","contenu":"<p>La <span class=\"kw-etio\">décontamination</span> digestive a une <strong>efficacité modeste</strong> et des indications strictes.</p>\n      <table >\n        <thead><tr><th>Méthode</th><th>Indications et conditions</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-ttt\">Charbon activé</span></td>\n            <td>Chélateur des substances <strong>carbo-adsorbables</strong> ; dose unique (répétée si forme à libération prolongée). Conditions : délai <span class=\"kw-chiffre\">≤ 1-2 h</span> après l'ingestion ; pas de trouble de conscience ni de déglutition</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Lavage gastrique</span></td>\n            <td>Substances <strong>non carbo-adsorbables</strong> engageant le <span class=\"kw-alerte\">pronostic vital</span> (typiquement <span class=\"kw-clinique\">les</span> sels de <span class=\"kw-ttt\">lithium</span>), intoxication &lt;<span class=\"kw-chiffre\"> 1 h</span>, sans trouble de conscience</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Irrigation intestinale</span></td>\n            <td>Substances non carbo-adsorbables à résorption retardée ; ingestion de fer</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Sirop d'ipéca</span></td>\n            <td><span class=\"kw-ci\">Ne doit plus être utilisé</span> (abandonné)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-ci\">Contre-indications</span> de la <span class=\"kw-etio\">décontamination</span> digestive.</strong> Ingestion de <span class=\"kw-ci\">caustiques</span>, d'<span class=\"kw-ci\">hydrocarbures</span>, de <span class=\"kw-ci\">produits moussants</span> ; <span class=\"kw-ci\">troubles de la conscience</span> chez un patient non intubé. Le charbon est en outre inefficace sur <span class=\"kw-clinique\">les</span> métaux (<span class=\"kw-ttt\">lithium</span>, plomb, fer) et le potassium.\n      </div>\n      <div class=\"callout callout-info\">\n        <strong>Épuration extrarénale.</strong> Indications limitées — moyen mnémotechnique « Aspire La DOUBLE Méth » : <span class=\"kw-ttt\">aspirine (salicylés)</span>, <span class=\"kw-ttt\">lithium</span>, <span class=\"kw-ttt\">méthanol / éthylène glycol</span>, <span class=\"kw-ttt\">metformine</span>.\n      </div>","frequence":1},{"id":"337-22","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principales manifestations des intoxications aiguës au cannabis, aux amphétamines, à la cocaïne, aux nouvelles drogues de synthèse","contenu":"<p><span class=\"kw-clinique\">Les</span> drogues festives donnent principalement deux toxidromes, parfois associés.</p>\n      <table >\n        <thead><tr><th>Toxidrome</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Adrénergique</span> / sympathomimétique<br>(<span class=\"kw-etio\">cocaïne</span>, <span class=\"kw-etio\">amphétamines</span>, LSD, drogues de synthèse — cathinones)</td>\n            <td>\n              <strong>Clinique « MATCH » :</strong> <span class=\"kw-clinique\">mydriase</span> ; <span class=\"kw-clinique\">agitation</span> ; <span class=\"kw-clinique\">coma</span>/<span class=\"kw-clinique\">confusion</span>/<span class=\"kw-clinique\">convulsions</span>/hallucinations ; <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">hyperthermie</span>, <span class=\"kw-clinique\">HTA</span> ; hyperventilation<br>\n              <strong>Biologie « 4H » :</strong> <span class=\"kw-bio\">hyperglycémie</span> ; hyperleucocytose ; hyperlactatémie ; <span class=\"kw-bio\">hypokaliémie</span><br>\n              <strong>Risque :</strong> épuisement cardiovasculaire → <span class=\"kw-alerte\">choc cardiogénique</span> par sidération myocardique\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Sérotoninergique</span><br>(<span class=\"kw-etio\">MDMA / ecstasy</span> surtout, cocaïne, drogues de synthèse)</td>\n            <td><span class=\"kw-alerte\">Hyperthermie 40-43 °C</span> ; myoclonies ; <span class=\"kw-clinique\">hyperréflexie</span> ; rigidité musculaire ; mydriase. Risque : <span class=\"kw-alerte\">choc, CIVD, rhabdomyolyse</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Pas d'antidote.</strong> Ces intoxications sont prises en charge de façon <strong>symptomatique</strong> (rééquilibration hydro-électrolytique, lutte contre l'<span class=\"kw-clinique\">hyperthermie</span>). Le <span class=\"kw-ttt\">labétalol</span> traite l'intoxication à la cocaïne, mais la cocaïne n'a <strong>pas d'antidote spécifique</strong> ; un effet stabilisant de membrane peut s'y associer.\n      </div>\n      <div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> <span class=\"kw-clinique\">Les</span> fiches sources détaillent les toxidromes adrénergique et sérotoninergique mais ne décrivent pas les manifestations propres de l'intoxication aiguë au <strong>cannabis</strong>. À enrichir depuis le Collège / Pilly.\n      </div>","frequence":0},{"id":"337-23","rang":"A","rubrique":"Epidémiologie","titre":"Intoxications aiguës de l’enfant : connaître les circonstances","contenu":"<p>Chez l'enfant, l'intoxication est le plus souvent <span class=\"kw-etio\">accidentelle</span> et <span class=\"kw-etio\">domestique</span>, à la différence de l'adulte (intoxication volontaire prédominante).</p>\n      <table >\n        <thead><tr><th>Élément</th><th>Donnée</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Toxiques fréquents au domicile</strong></td>\n            <td>Le <span class=\"kw-ttt\">paracétamol</span> est l'antipyrétique/<span class=\"kw-ttt\">antalgique</span> le plus prescrit chez l'enfant — d'où sa grande disponibilité au domicile et son rôle dans <span class=\"kw-clinique\">les</span> intoxications accidentelles</td>\n          </tr>\n          <tr>\n            <td><strong>Monoxyde de carbone</strong></td>\n            <td><span class=\"kw-clinique\">Les</span> enfants représentent <span class=\"kw-chiffre\">~20 %</span> des intoxications au CO et y sont particulièrement vulnérables</td>\n          </tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Âge</th><th>Contexte typique</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Avant <span class=\"kw-chiffre\">1 an</span></strong></td><td>Erreur d'administration d'un médicament par un parent (erreur de dose, médicament inapproprié) — <span class=\"kw-chiffre\">~25 %</span> des cas</td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">1–8 ans</span></strong></td><td>Intoxication <span class=\"kw-etio\">accidentelle</span>, exploratoire (ingestion d'un produit unique au domicile)</td></tr>\n          <tr><td><strong>&gt;<span class=\"kw-chiffre\"> 10 ans</span></strong></td><td>Intoxication plutôt <span class=\"kw-etio\">volontaire / intentionnelle</span></td></tr>\n          <tr><td><strong>Adolescent</strong> (surtout fille)</td><td><span class=\"kw-etio\">IMV</span> volontiers polymédicamenteuse</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Facteur de risque</span> domestique</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Horaires de pic</strong></td><td><span class=\"kw-chiffre\">11–13 h</span> et <span class=\"kw-chiffre\">18–20 h</span> (préparation des repas, <span class=\"kw-def\">surveillance</span> moindre)</td></tr>\n          <tr><td><strong>Pièces à risque</strong></td><td>Cuisine, salle de bains, toilettes (exposition aux produits ménagers)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Rôle du CAP.</strong> Dans <span class=\"kw-chiffre\">&gt; 60 %</span> des cas, la situation est gérée par téléphone par le <strong>Centre antipoison (CAP)</strong>, sans consultation médicale.\n      </div>","frequence":0},{"id":"337-24","rang":"A","rubrique":"Identifier une urgence","titre":"Intoxications aiguës de l’enfant : identifier les situations d’urgence selon le terrain et le toxique","contenu":"<p>Chez l'enfant, certaines associations <span class=\"kw-etio\">toxique</span>/<span class=\"kw-def\">terrain</span> imposent une prise en charge urgente.</p>\n      <table >\n        <thead><tr><th>Toxique</th><th>Signes d'<span class=\"kw-alerte\">urgence</span> chez l'enfant</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Monoxyde de carbone</span></td>\n            <td>\n              <strong>Gravité :</strong> troubles de conscience avec <span class=\"kw-alerte\">trismus</span>, <span class=\"kw-clinique\">convulsions</span> ; <span class=\"kw-def\">HTA</span>, <span class=\"kw-clinique\">hyperthermie</span>, <span class=\"kw-clinique\">tachycardie</span> ; <span class=\"kw-alerte\">détresse</span> respiratoire ; <span class=\"kw-imagerie\">trouble du rythme ou de la repolarisation à l'ECG</span><br>\n              <strong>Facteurs aggravants :</strong> intoxication aux fumées d'incendie ; lésions traumatiques associées ; perte de connaissance ; <span class=\"kw-chiffre\">HbCO &gt; 15 %</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Paracétamol</span></td>\n            <td><span class=\"kw-alerte\">Urgence</span> à la <span class=\"kw-ttt\">N-acétylcystéine</span> si dose ingérée <span class=\"kw-chiffre\">&gt; 150 mg/kg</span>, ingestion datant de <span class=\"kw-chiffre\">&gt; 8 h</span>, signes de toxicité, ou poly-intoxication ; risque d'<span class=\"kw-alerte\">hépatite fulminante</span> (&lt;<span class=\"kw-chiffre\"> 1 %</span> des enfants intoxiqués)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> <span class=\"kw-clinique\">Les</span> fiches sources couvrent le CO et le <span class=\"kw-ttt\">paracétamol</span> mais ne dressent pas la liste exhaustive des situations d'<span class=\"kw-alerte\">urgence</span> pédiatriques selon le <span class=\"kw-def\">terrain</span> et le <span class=\"kw-etio\">toxique</span>. À enrichir depuis le Collège / Pilly.\n      </div>","frequence":0},{"id":"337-25","rang":"A","rubrique":"Prise en charge","titre":"Intoxications aiguës de l’enfant : connaître les principes de prise en charge","contenu":"<p>La prise en charge pédiatrique reprend <span class=\"kw-clinique\">les</span> principes de l'adulte (traitement symptomatique guidé par les défaillances d'organe, antidotes), avec quelques particularités illustrées par les deux intoxications les mieux documentées.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-etio\">Toxique</span></th><th>Prise en charge chez l'enfant</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Monoxyde de carbone</span></td>\n            <td>\n              <strong>Domicile :</strong> appel du 15, équipe médicalisée avec détecteur de CO, aération<br>\n              <strong>Initial :</strong> approche <span class=\"kw-clinique\">ABCDE</span> ; <span class=\"kw-ttt\">O₂ au masque haute concentration &gt; 8 L/min</span>, ou <span class=\"kw-ttt\">intubation</span>/ventilation si troubles de conscience ; HbCO précoce + <span class=\"kw-bio\">ECG</span><br>\n              <strong>Hospitalier :</strong> <span class=\"kw-ttt\">oxygénothérapie</span> <span class=\"kw-chiffre\">≥ 12 h</span> ; <strong>indications larges d'oxygénothérapie hyperbare</strong> (perte de connaissance même brève, troubles de conscience, <span class=\"kw-clinique\">convulsions</span>, signes neurologiques, troubles du rythme)\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Paracétamol</span></td>\n            <td><span class=\"kw-ttt\">N-acétylcystéine</span> dès l'arrivée si forte suspicion, signes de toxicité, ingestion &gt;<span class=\"kw-chiffre\"> 8 h</span>, dose &gt;<span class=\"kw-chiffre\"> 150 mg/kg</span> ou poly-intoxication ; sinon après H4 selon la paracétamolémie reportée sur le nomogramme</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> <span class=\"kw-clinique\">Les</span> fiches sources illustrent la PEC pédiatrique via le CO et le <span class=\"kw-ttt\">paracétamol</span> mais n'énoncent pas de principes généraux structurés (rôle du centre antipoison, modalités de <span class=\"kw-def\">surveillance</span>, orientation). À enrichir depuis le Collège / Pilly.\n      </div>","frequence":0},{"id":"337-26","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Intoxications aiguës de l’enfant : savoir prévenir","contenu":"<p>La prévention s'appuie notamment sur <span class=\"kw-clinique\">les</span> obl<span class=\"kw-chiffre\">iga</span>tions de <span class=\"kw-def\">signalement</span>, qui permettent d'identifier les sources et d'éviter les récidives.</p>\n      <table >\n        <thead><tr><th>Mesure</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Signalement</span> du CO</strong></td>\n            <td><span class=\"kw-def\">Signalement</span> <strong>obl<span class=\"kw-chiffre\">iga</span>toire</strong> à l'<span class=\"kw-def\">ARS</span> via le centre antipoison ; enquête technique pour identifier la source et éviter <span class=\"kw-clinique\">les</span> récidives</td>\n          </tr>\n          <tr>\n            <td><strong>Déclaration</strong></td>\n            <td>Enquête technique et déclaration obl<span class=\"kw-chiffre\">iga</span>toires en cas d'intoxication domestique au monoxyde de carbone</td>\n          </tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Mesure préventive</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Rangement</strong></td><td>Médicaments et produits d'entretien <strong>hors de portée</strong> des enfants et en hauteur</td></tr>\n          <tr><td><strong>Conditionnements de sécurité</strong></td><td>Bouchons/conditionnements pédiatriques ; emballage unitaire des médicaments (blisters)</td></tr>\n          <tr><td><strong>Caustiques</strong></td><td>Généralisation des <strong>fermetures sécurisées</strong> pour <span class=\"kw-clinique\">les</span> produits caustiques</td></tr>\n          <tr><td><strong>Contenants</strong></td><td>Ne jamais transvaser un produit ménager dans un récipient à usage alimentaire (bouteille) ; distinguer contenants alimentaires / ménagers</td></tr>\n        </tbody>\n      </table>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré :</strong> <span class=\"kw-alerte\">urgence</span> vitale potentielle ; <span class='kw-alerte'>aggravation secondaire fréquente</span> (patient conscient à l'arrivée pouvant évoluer vers le <span class='kw-clinique'><span class=\"kw-alerte\">coma</span></span> → <span class=\"kw-def\">réévaluation</span> répétée)<br><strong>Fenêtre :</strong> <span class='kw-ttt'>charbon activé</span> ≤ <span class='kw-chiffre'><span class=\"kw-chiffre\">1-2h</span></span> ; <span class='kw-ttt'>lavage gastrique</span> &lt; <span class='kw-chiffre'><span class=\"kw-chiffre\">1h</span></span> ; <span class='kw-ttt'><span class=\"kw-ttt\">N-acétylcystéine</span></span> idéalement &lt; <span class='kw-chiffre'><span class=\"kw-chiffre\">8-10h</span></span> (au plus tard <span class='kw-chiffre'>H12</span>) ; <span class='kw-ttt'>O2</span> dans le CO le plus précoce possible<br><strong>1er geste :</strong> évaluation des <span class='kw-clinique'>1ères secondes</span> (<span class=\"kw-chiffre\">Glasgow</span>, ventilation spontanée, signes de <span class=\"kw-alerte\">choc</span>) + <span class='kw-bio'><span class=\"kw-bio\">glycémie</span> capillaire</span> et température, puis <span class='kw-ttt'>O2</span>, scope, PLS, appel à l'aide</p>","hospit":"<p><strong>Ambulatoire :</strong> patient <span class='kw-def'>asymptomatique</span> (<span class=\"kw-chiffre\">Glasgow</span> ≥ <span class='kw-chiffre'>14</span>, <span class=\"kw-imagerie\">ECG</span> normal, pas d'anomalie CV/respiratoire) + <span class=\"kw-etio\">toxique</span> identifié à <span class='kw-def'>libération immédiate</span>, non lésionnel, sans atteinte cardiaque → <span class=\"kw-def\">surveillance</span> discontinue <span class='kw-chiffre'><span class=\"kw-chiffre\">4-6h</span></span> puis sortie<br><strong>Hospit :</strong> <span class='kw-alerte'>toute intoxication volontaire</span> (même sans gravité, risque d'aggravation/récidive) ; tout <span class='kw-def'>toxique à risque</span> (fonctionnel cardiaque, <span class='kw-etio'>lésionnel</span>, libération prolongée)<br><strong>Réa / <span class=\"kw-alerte\">USI</span> :</strong> patient <span class='kw-alerte'>symptomatique</span> (Glasgow &lt; <span class='kw-chiffre'>14</span>, <span class=\"kw-imagerie\">ECG</span> anormal, anomalie CV/respiratoire), <span class='kw-etio'>cardiotropes</span> → surveillance continue monitorée</p>","redflags":"<ul><li><span class='kw-clinique'>Trouble de la conscience</span> : <span class=\"kw-chiffre\">Glasgow</span> &lt; <span class='kw-chiffre'>14</span>, a fortiori <span class=\"kw-alerte\">coma</span> (sa profondeur fait la gravité des psychotropes)</li><li><span class='kw-clinique'>Détresse respiratoire</span> : <span class=\"kw-clinique\">bradypnée</span>, hypoventilation centrale, encombrement / <span class=\"kw-clinique\">pneumopathie d'inhalation</span></li><li><span class='kw-alerte'>État de choc</span> ou <span class=\"kw-alerte\">arrêt cardiaque</span></li><li><span class='kw-clinique'><span class=\"kw-imagerie\">ECG</span></span> anormal : <span class='kw-etio'>effet stabilisant de membrane</span> (QRS &gt; <span class='kw-chiffre'>120 ms</span>, arythmies ventriculaires)</li><li><span class='kw-clinique'>Convulsions</span> ; <span class='kw-clinique'>hyperthermie</span> sévère (syndrome sérotoninergique <span class='kw-chiffre'><span class=\"kw-chiffre\">40-43°C</span></span>, syndrome malin des neuroleptiques)</li><li><span class='kw-alerte'>Aggravation secondaire</span> : <span class=\"kw-clinique\">les</span> défaillances d'organe doivent être réévaluées de façon répétée (processus dynamique)</li><li>Enfant : produits dangereux <strong>même à faible dose</strong> — <span class='kw-ttt'><span class=\"kw-ttt\">inhibiteurs calciques</span></span>, <span class='kw-ttt'>clonidine</span>, <span class='kw-ttt'>tricycliques</span>, <span class='kw-ttt'><span class=\"kw-ttt\">opiacés</span></span>, <span class='kw-ttt'>salicylés</span>, <span class='kw-ttt'><span class=\"kw-ttt\">sulfamides hypoglycémiants</span></span></li></ul>","principes":"<p><strong>Traitement symptomatique (guidé par la <span class=\"kw-alerte\">défaillance</span> d'organe)</strong></p><ul><li><span class='kw-ttt'>Protection des VAS</span> par <span class=\"kw-ttt\">intubation</span>-ventilation si <span class=\"kw-chiffre\">Glasgow</span> &lt; <span class='kw-chiffre'>8</span> non réversible par antidote</li><li>Prise en charge d'une <span class='kw-clinique'>pneumopathie d'inhalation</span></li><li>État de <span class=\"kw-alerte\">choc</span> : <span class='kw-ttt'>remplissage</span> initial (sauf <span class=\"kw-alerte\">OAP</span>) puis <span class='kw-ttt'><span class=\"kw-ttt\">noradrénaline</span></span> si insuffisant</li><li><span class='kw-ttt'>ECMO</span> veino-artérielle si <span class='kw-alerte'><span class=\"kw-alerte\">choc cardiogénique</span></span> ou <span class='kw-alerte'><span class=\"kw-alerte\">arrêt cardiaque</span> réfractaire</span></li><li><span class='kw-ttt'>Épuration extrarénale</span> si <span class=\"kw-ci\">insuffisance rénale</span> ou trouble métabolique grave</li></ul><p><strong><span class=\"kw-etio\">Décontamination</span> digestive (indications limitées)</strong></p><p><span class='kw-ci'>CI</span> : caustiques, hydrocarbures, produits moussants, métaux lourds (<span class=\"kw-ttt\">lithium</span>, plomb, fer), troubles de conscience chez un patient non intubé</p><ul><li><span class='kw-ttt'>Charbon activé</span> : <span class=\"kw-etio\">toxique</span> carbo-adsorbable, délai ≤ <span class='kw-chiffre'><span class=\"kw-chiffre\">1-2h</span></span>, pas de trouble de conscience/déglutition ; dose unique (répétée si forme LP)</li><li><span class='kw-ttt'>Lavage gastrique</span> : substances non carbo-adsorbables menaçant le <span class=\"kw-alerte\">pronostic vital</span>, &lt; <span class='kw-chiffre'><span class=\"kw-chiffre\">1h</span></span> (ex. <span class='kw-etio'><span class=\"kw-ttt\">lithium</span></span>)</li><li><span class='kw-ttt'>Sirop d'ipéca</span> : abandonné</li></ul><p><strong>Épuration extrarénale (dialyse)</strong></p><ul><li>Indications limitées : <span class='kw-etio'>salicylés</span>, <span class='kw-etio'><span class=\"kw-ttt\">lithium</span></span>, <span class='kw-etio'>méthanol / éthylène glycol</span>, <span class='kw-etio'><span class=\"kw-ttt\">metformine</span></span></li></ul><p><strong>Antidotes spécifiques</strong></p><ul><li><span class='kw-etio'>Paracétamol</span> → <span class='kw-ttt'><span class=\"kw-ttt\">N-acétylcystéine</span></span> (régénère le glutathion ; dosage interprétable dès <span class='kw-chiffre'>H4</span>, nomogramme de Rumack-Matthew)</li><li><span class='kw-etio'>Morphiniques</span> → <span class='kw-ttt'><span class=\"kw-ttt\">naloxone</span></span> ; <span class='kw-etio'><span class=\"kw-ttt\">benzodiazépines</span></span> → <span class='kw-ttt'>flumazénil</span></li><li><span class='kw-etio'>CO</span> → <span class='kw-ttt'>oxygène normobare</span> (≥ <span class='kw-chiffre'><span class=\"kw-chiffre\">12h</span></span>) et <span class='kw-ttt'>hyperbare</span> (signes neuro, <span class=\"kw-alerte\">ischémie myocardique</span>, HbCO &gt; <span class='kw-chiffre'><span class=\"kw-chiffre\">25%</span></span>, femme enceinte, enfant)</li><li><span class='kw-etio'>Cyanure</span> (fumées d'incendie) → <span class='kw-ttt'>hydroxocobalamine</span> (<span class=\"kw-bio\">vitamine B12</span>)</li><li><span class='kw-etio'>Effet stabilisant de membrane</span> → <span class='kw-ttt'>bicarbonate de sodium molaire <span class=\"kw-chiffre\">8,4%</span></span> (uniquement si QRS élargis)</li><li><span class='kw-etio'>Digoxine</span> → <span class='kw-ttt'>anticorps anti-digoxine (Fab)</span> ; <span class='kw-etio'>β-bloquants</span> → <span class='kw-ttt'><span class=\"kw-ttt\">glucagon</span></span> ; <span class='kw-etio'><span class=\"kw-ttt\">inhibiteurs calciques</span></span> → <span class='kw-ttt'>sels de calcium + <span class=\"kw-ttt\">insuline</span>/glucose</span></li><li><span class='kw-etio'>Méthanol / éthylène glycol</span> → <span class='kw-ttt'>fomépizole (4-MP)</span> ± <span class='kw-ttt'>hémodialyse</span></li></ul><p><strong>Spécificités pédiatriques</strong></p><ul><li>Avant toute action : <span class='kw-ttt'>appeler le centre antipoison</span> (&gt; <span class='kw-chiffre'><span class=\"kw-chiffre\">60%</span></span> des cas gérés par téléphone)</li><li><strong>Ne rien faire boire, ne pas faire vomir</strong></li><li>Tenir compte de la dose maximale possible ; connaître le poids ; se méfier d'un autre produit</li><li>Évaluation systématique selon la séquence <span class='kw-def'>ABCDE</span></li></ul>","suivi":"<p><strong>Avis psychiatrique :</strong> <span class='kw-alerte'>systématique avant la sortie</span> pour toute intoxication volontaire (imposé médico-légalement) → intentionnalité suicidaire, risque de récidive, adhésion aux soins ; orientation ambulatoire (consultation en CMP &lt; <span class='kw-chiffre'><span class=\"kw-chiffre\">48h</span></span>) ou <span class=\"kw-alerte\">hospitalisation</span><br><strong><span class=\"kw-def\">Réévaluation</span> :</strong> <span class=\"kw-clinique\">les</span> défaillances d'organe = processus <span class='kw-alerte'>dynamique et répété</span><br><strong>Centre antipoison :</strong> aide diagnostique/thérapeutique + toxicovigilance (enquête si intoxication collective)<br><strong>Déclarations :</strong> CO domestique → enquête technique + déclaration <span class=\"kw-def\">ARS</span> ; suspicion d'intoxication professionnelle → médecine du travail<br><strong><span class=\"kw-def\">Suivi</span> CO :</strong> consultation de contrôle à <span class='kw-chiffre'><span class=\"kw-chiffre\">1 mois</span></span> (séquelles) ; <span class='kw-etio'>syndrome post-intervallaire</span> à <span class='kw-chiffre'>2-40 j</span></p>"},"liensGlobaux":[{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/56.%20Intoxications%20aigu%C3%ABs.pdf","label":"CeMIR — 56. intoxications aiguës"},{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/urgences-reanimation-chirurgie-orthopedique/intoxications-aigues","label":"Pedia-univ — Intoxications aigues"},{"href":"https://urgences-serveur.fr/intoxication-au-co.html","label":"Intoxication au co"},{"href":"https://www.sfmu.org/toxin/PROTOCOL/PARACET/PARACETC.HTM","label":"Collège — Paracetc"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Intoxication aiguë confirmée ou suspectée — Évaluation de gravité immédiate : Glasgow, CV, respiratoire, ECG, glycémie, température","detail":"<h4>CAT — orientation devant une intoxication aiguë — Stratification de la gravité → niveau de <span class=\"kw-def\">surveillance</span> et d'orientation</h4>","branches":[{"to":"q-gravite","label":"Bilan initial réalisé","color":"blue"}]},{"id":"q-gravite","kind":"decision","label":"<span class=\"kw-alerte\">Signes de gravité</span> immédiate ? — <span class=\"kw-chiffre\">Glasgow</span> <span class=\"kw-chiffre\">< 14,</span> anomalie CV ou respiratoire, <span class=\"kw-imagerie\">ECG</span> anormal","branches":[{"to":"t-rea","label":"Oui — patient symptomatique","color":"red"},{"to":"q-risque","label":"Non — asymptomatique (Glasgow ≥ 14, ECG normal)","color":"green"}]},{"id":"t-rea","kind":"terminal","label":"Réanimation / USI — hospitalisation impérative","color":"red","detail":"<h4>Conduite</h4><ul><li>Unité adaptée : <span class='s-med'><span class=\"kw-alerte\">réanimation</span></span>, USC ou UHCD</li><li><span class='s-med'><span class=\"kw-def\">Surveillance</span> continue</span> monitorée (scope, <span class=\"kw-bio\">SpO2</span>, PA)</li><li>Traitement symptomatique guidé par la <span class=\"kw-alerte\">défaillance</span> : <span class='s-med'>protection des VAS</span> si <span class=\"kw-chiffre\">Glasgow</span> &lt; <span class='s-nb'>8</span>, remplissage ± <span class='s-med'><span class=\"kw-ttt\">noradrénaline</span></span>, <span class='s-med'>ECMO</span> si <span class=\"kw-alerte\">choc cardiogénique</span> / <span class=\"kw-alerte\">ACR</span> réfractaire</li><li>Traitement toxicologique selon besoins : <span class='s-med'>antidote</span>, <span class='s-med'><span class=\"kw-etio\">décontamination</span></span>, <span class='s-med'>épuration extrarénale</span></li></ul>"},{"id":"q-risque","kind":"decision","label":"Toxique à risque ? — Fonctionnel cardiaque, lésionnel, ou à libération prolongée","branches":[{"to":"t-hospit","label":"Oui","color":"amber"},{"to":"q-volontaire","label":"Non — toxique identifié, libération immédiate, non lésionnel","color":"green"}]},{"id":"t-hospit","kind":"terminal","label":"Hospitalisation + surveillance prolongée","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-def\">Surveillance</span> prolongée : <span class='s-etio'><span class=\"kw-etio\">toxique</span> lésionnel</span> ou à <span class='s-def'>libération prolongée</span> = aggravation retardée possible (phase initiale parfois asymptomatique)</li><li>Bilan guidé par le <span class=\"kw-etio\">toxique</span> : <span class='s-etio'><span class=\"kw-ttt\">paracétamol</span></span> → <span class=\"kw-bio\">bilan hépatique</span> + <span class='s-bio'><span class=\"kw-bio\">TP</span></span> ; <span class='s-etio'>cardiotrope</span> → <span class=\"kw-imagerie\">ETT</span> + <span class='s-bio'><span class=\"kw-bio\">lactate</span></span></li><li>Avis du <span class='s-med'>centre antipoison</span></li></ul>"},{"id":"q-volontaire","kind":"decision","label":"Intoxication volontaire ?","branches":[{"to":"t-imv","label":"Oui","color":"amber"},{"to":"t-ambu","label":"Non — accidentelle","color":"green"}]},{"id":"t-imv","kind":"terminal","label":"Hospitalisation systématique + avis psychiatrique","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class='s-grav'><span class=\"kw-alerte\">Hospitalisation</span> imposée devant toute intoxication volontaire</span>, même sans gravité (risque d'aggravation secondaire / récidive)</li><li><span class=\"kw-def\">Surveillance</span> discontinue de quelques heures (<span class='s-nb'><span class=\"kw-chiffre\">4-6h</span></span> selon dose et demi-vie)</li><li><span class='s-grav'>Évaluation psychiatrique / addictologique systématique avant la sortie</span> (médico-légal)</li></ul>"},{"id":"t-ambu","kind":"terminal","label":"Surveillance simple puis sortie","color":"green","detail":"<h4>Conduite</h4><ul><li>Aucun geste toxicologique ni symptomatique nécessaire</li><li><span class=\"kw-def\">Surveillance</span> discontinue de quelques heures (<span class='s-nb'><span class=\"kw-chiffre\">4-6h</span></span>)</li><li>Sortie après <span class=\"kw-def\">surveillance</span></li></ul>"}]},"cards":[{"i":"1ef809abed2f","n":337,"o":"337-10","u":"Prise en charge","t":"Savoir mettre en œuvre le traitement symptomatique à la phase initiale","q":"Quelle est la priorité du traitement symptomatique d'une intoxication aiguë à la phase initiale ?","a":"<p>La priorité est la prise en charge d'une <strong>défaillance d'organe</strong>, sans spécificité toxicologique. Ce traitement prime sur le traitement spécifique.</p>"},{"i":"3a8b6f03abdd","n":337,"o":"337-10","u":"Prise en charge","t":"Savoir mettre en œuvre le traitement symptomatique à la phase initiale","q":"Quand réalise-t-on une épuration extrarénale au cours d'une intoxication aiguë ?","a":"<p>Une épuration extrarénale est indiquée en cas d'<strong>insuffisance rénale</strong> ou de <strong>trouble métabolique grave</strong>.</p>"},{"i":"94ac3754c579","n":337,"o":"337-10","u":"Prise en charge","t":"Savoir mettre en œuvre le traitement symptomatique à la phase initiale","q":"Quelle est la prise en charge spécifique en cas de choc cardiogénique ou d'arrêt cardiaque réfractaire lors d'une intoxication aiguë ?","a":"<p>En cas de choc cardiogénique ou d'arrêt cardiaque réfractaire, l'indication formelle est l'<strong>ECMO veino-artérielle</strong> (oxygénation par membrane extracorporelle).</p>"},{"i":"a3df584692f3","n":337,"o":"337-10","u":"Prise en charge","t":"Savoir mettre en œuvre le traitement symptomatique à la phase initiale","q":"Comment prend-on en charge la défaillance neurologique dans le cadre d'une intoxication aiguë, à la phase initiale ?","a":"<p>En cas de défaillance neurologique (notamment si le score de Glasgow est <strong>inférieur à 8</strong> et non réversible par un antidote), la prise en charge consiste en la <strong>protection des voies aériennes</strong> par intubation-ventilation.</p>"},{"i":"cb93331dcf09","n":337,"o":"337-10","u":"Prise en charge","t":"Savoir mettre en œuvre le traitement symptomatique à la phase initiale","q":"Comment prend-on en charge l'état de choc hémodynamique au cours d'une intoxication aiguë, à la phase initiale ?","a":"<p>La prise en charge de l'état de choc hémodynamique débute par un <strong>remplissage initial</strong> (sauf en cas d'œdème aigu du poumon manifeste). Si cette mesure est insuffisante, des <strong>catécholamines</strong> sont administrées, typiquement la <strong>noradrénaline</strong> pour ses effets α vasoconstricteurs et β inotropes.</p>"},{"i":"073186c5cd3d","n":337,"o":"337-13","u":"Prise en charge","t":"Savoir demander un avis psychiatrique systématique en cas d’intoxication volontaire","q":"L'hospitalisation est-elle systématique en cas d'intoxication volontaire ?","a":"<p>Oui, une <strong>hospitalisation est indiquée</strong> devant toute intoxication volontaire, <strong>même en l'absence de signe de gravité</strong>, en raison du <strong>risque élevé d'aggravation secondaire et de récidive</strong> dans un contexte psychiatrique.</p>"},{"i":"0dd804d196e4","n":337,"o":"337-13","u":"Prise en charge","t":"Savoir demander un avis psychiatrique systématique en cas d’intoxication volontaire","q":"Quelle est la règle concernant l'évaluation psychiatrique d'un patient hospitalisé pour une intoxication médicamenteuse volontaire ?","a":"<p>Tout patient hospitalisé pour une <strong>intoxication médicamenteuse volontaire</strong> doit bénéficier d'une <strong>évaluation psychiatrique</strong> (ou addictologique si contexte de toxicomanie) <strong>avant la sortie</strong>. Il s'agit d'une <strong>obligation médico-légale</strong>.</p>"},{"i":"5f8d47ce19ca","n":337,"o":"337-13","u":"Prise en charge","t":"Savoir demander un avis psychiatrique systématique en cas d’intoxication volontaire","q":"Quelles sont les orientations possibles après l'évaluation psychiatrique d'une intoxication volontaire ?","a":"<ul><li><strong>Consultation</strong> en <strong>centre médico-psychologique</strong> dans les <strong>48 heures</strong> après la sortie.</li><li><strong>Hospitalisation complète</strong>, avec ou sans consentement, si nécessaire.</li></ul>"},{"i":"dce3be6fa05e","n":337,"o":"337-13","u":"Prise en charge","t":"Savoir demander un avis psychiatrique systématique en cas d’intoxication volontaire","q":"Quels sont les objectifs de l'évaluation psychiatrique d'un patient victime d'intoxication volontaire ?","a":"<ul><li>Évaluer l'<strong>intentionnalité suicidaire</strong>.</li><li>Évaluer le <strong>risque de récidive immédiat</strong>.</li><li>Évaluer la disponibilité de l'entourage.</li><li>Évaluer l'<strong>adhésion aux soins</strong>.</li></ul>"},{"i":"188f522970a8","n":337,"o":"337-17","u":"Prise en charge","t":"Savoir diagnostiquer une intoxication aiguë au monoxyde de carbone et connaître les principes de prise en charge chez l’adulte et l’enfant","q":"Quelle est la physiopathologie principale de l'intoxication au monoxyde de carbone (CO) et quels sont les organes cibles ?","a":"<p>Le monoxyde de carbone (CO) a une affinité <strong>230 fois supérieure</strong> à celle de l'oxygène pour l'hémoglobine, entraînant la formation de <strong>carboxyhémoglobine (HbCO)</strong> et une <strong>hypoxie cellulaire</strong>. Les chaînes respiratoires mitochondriales sont également inhibées. Les principaux organes cibles sont le <strong>cerveau</strong> et le <strong>myocarde</strong>.</p>"},{"i":"1f59e35a4722","n":337,"o":"337-17","u":"Prise en charge","t":"Savoir diagnostiquer une intoxication aiguë au monoxyde de carbone et connaître les principes de prise en charge chez l’adulte et l’enfant","q":"Quels sont les signes cliniques d'intoxication au monoxyde de carbone qui justifient le recours à l'oxygénothérapie hyperbare ?","a":"<p>L'oxygénothérapie hyperbare est indiquée dans les formes graves présentant :</p><ul><li>Des <strong>signes neurologiques</strong> (perte de connaissance, irritation pyramidale).</li><li>Une <strong>ischémie myocardique</strong>.</li><li>Un taux d'<strong>HbCO > 25 %</strong>.</li><li>Elle est systématique chez la <strong>femme enceinte</strong> et les indications sont larges chez l'<strong>enfant</strong>.</li></ul>"},{"i":"2087d4329715","n":337,"o":"337-17","u":"Prise en charge","t":"Savoir diagnostiquer une intoxication aiguë au monoxyde de carbone et connaître les principes de prise en charge chez l’adulte et l’enfant","q":"Quel est le suivi recommandé après une intoxication au monoxyde de carbone et quelle complication peut survenir à distance ?","a":"<p>Un <strong>signalement obligatoire</strong> à l'ARS via le centre antipoison est nécessaire. Une <strong>consultation de contrôle à 1 mois</strong> est recommandée pour dépister des séquelles. Une complication possible est le <strong>syndrome post-intervallaire</strong>, apparaissant vers <strong>3 semaines</strong> (entre 2 et 40 jours), pouvant se manifester par des troubles mnésiques, du comportement, des céphalées chroniques, une démence précoce ou des crises convulsives.</p>"},{"i":"41654ce34ce6","n":337,"o":"337-17","u":"Prise en charge","t":"Savoir diagnostiquer une intoxication aiguë au monoxyde de carbone et connaître les principes de prise en charge chez l’adulte et l’enfant","q":"Quel est un piège diagnostic majeur concernant l'oxymétrie de pouls (SpO₂) dans l'intoxication au monoxyde de carbone ?","a":"<p>La <strong>SpO₂</strong> et la <strong>SaO₂</strong> sont <strong>faussement rassurantes</strong> car les appareils de mesure ne distinguent pas la carboxyhémoglobine (HbCO) de l'oxyhémoglobine (HbO₂), et lisent l'HbCO comme de l'HbO₂. Seule une valeur anormale d'<strong>HbCO</strong> a de l'intérêt diagnostique.</p>"},{"i":"b369f736e868","n":337,"o":"337-17","u":"Prise en charge","t":"Savoir diagnostiquer une intoxication aiguë au monoxyde de carbone et connaître les principes de prise en charge chez l’adulte et l’enfant","q":"Quels sont les principes des traitements initiaux et spécifiques de l'intoxication aiguë au monoxyde de carbone ?","a":"<ul><li><strong>Éviction :</strong> aération des locaux, arrêt de la source, évacuation de la zone contaminée.</li><li><strong>Oxygénothérapie normobare :</strong> <strong>O₂ pur au masque haute concentration 15 L/min</strong>, débutée en préhospitalier, poursuivie <strong>≥ 12 h</strong> (permet de réduire la demi-vie du CO de 3-4h en air ambiant à 30-40 min).</li><li><strong>Oxygénothérapie hyperbare :</strong> indiquée dans les formes graves (signes neurologiques, ischémie myocardique, HbCO &gt; 25 %, femme enceinte, enfant).</li></ul>"},{"i":"c29cc29d91da","n":337,"o":"337-17","u":"Prise en charge","t":"Savoir diagnostiquer une intoxication aiguë au monoxyde de carbone et connaître les principes de prise en charge chez l’adulte et l’enfant","q":"Quels sont les signes cliniques distinctifs d'une intoxication aiguë au monoxyde de carbone, selon sa gravité ?","a":"<ul><li><strong>Formes bénignes :</strong> <strong>céphalées</strong> (90%), évocatrices si nocturnes/disparaissant le matin ou survenant dans une pièce précise ; asthénie, nausées, vertiges, sensation ébrieuse.</li><li><strong>Formes graves :</strong> coma hypertonique avec irritation pyramidale, comitialité ; anomalies ECG (troubles du rythme, ischémie) ; collapsus, œdème pulmonaire.</li><li><strong>Signe spécifique en cas d'intoxication massive :</strong> <strong>teinte cochenille des téguments</strong>.</li></ul>"},{"i":"8582e32a3492","n":337,"o":"337-18","u":"Prise en charge","t":"Connaître les principes de prise en charge d’une intoxication alcoolique aiguë","q":"Comment l'éthanol agit-il comme toxique fonctionnel dans le cadre d'une intoxication alcoolique aiguë et quel toxidrome provoque-t-il ?","a":"<p>L'éthanol est un <strong>toxique fonctionnel</strong> entraînant un <strong>toxidrome de myorelaxation</strong>. Ce toxidrome se caractérise par :</p><ul><li>Un <strong>coma calme hypotonique</strong></li><li>Une <strong>hyporéflexie</strong></li><li>Une <strong>dysarthrie</strong></li><li>Une <strong>bradypnée</strong></li></ul>"},{"i":"abcc38ea5c53","n":337,"o":"337-18","u":"Prise en charge","t":"Connaître les principes de prise en charge d’une intoxication alcoolique aiguë","q":"Quel est le diagnostic différentiel majeur à éliminer en présence d'une intoxication alcoolique aiguë, et dans quelle situation faut-il réaliser un examen complémentaire ?","a":"<p>Le diagnostic différentiel majeur à éliminer est un <strong>traumatisme crânien passé inaperçu</strong>. Il faut réaliser un <strong>TDM cérébrale</strong> si le trouble de la vigilance <strong>n'est pas entièrement expliqué par l'alcoolémie</strong>.</p>"},{"i":"dbbee599b9f4","n":337,"o":"337-18","u":"Prise en charge","t":"Connaître les principes de prise en charge d’une intoxication alcoolique aiguë","q":"Quels sont les principes de la prise en charge symptomatique d'une intoxication alcoolique aiguë ?","a":"<p>La prise en charge symptomatique d'une intoxication alcoolique aiguë comprend :</p><ul><li>La <strong>protection des voies aériennes</strong></li><li>La <strong>surveillance</strong> de la conscience, de la glycémie et de la température</li><li>Le <strong>réchauffement</strong> en cas d'hypothermie</li><li>L'<strong>hydratation</strong></li></ul>"},{"i":"debf04b1a7fa","n":337,"o":"337-18","u":"Prise en charge","t":"Connaître les principes de prise en charge d’une intoxication alcoolique aiguë","q":"Quels sont les principaux risques à surveiller chez un patient présentant une intoxication alcoolique aiguë ?","a":"<p>Les principaux risques chez un patient en intoxication alcoolique aiguë sont :</p><ul><li>L'<strong>hypothermie</strong> (due à l'action centrale de l'alcool sur la thermorégulation et/ou à l'exposition au froid)</li><li>L'<strong>obstruction des voies aériennes</strong></li><li>L'<strong>inhalation</strong> de vomissements</li></ul>"},{"i":"528d0f6af47b","n":337,"o":"337-20","u":"Prise en charge","t":"Connaître les principes de protection en cas d’évènement chimique de grande ampleur","q":"Comment l'hôpital doit-il anticiper et se protéger lors de l'afflux de victimes d'une intoxication de grande ampleur, avant même les soins ?","a":"<p>Avant d'accueillir les victimes d'une intoxication de grande ampleur, l'hôpital doit :</p><ul><li><strong>Fermer les portes des urgences</strong> pour éviter l'entrée non contrôlée de victimes contaminées.</li><li>Mettre en place un <strong>périmètre de sécurité</strong> et une <strong>chaîne de décontamination</strong>.</li><li>Procéder à une <strong>réorganisation des urgences et de tout l'hôpital</strong> pour gérer la situation.</li></ul>"},{"i":"5428353d4a2c","n":337,"o":"337-20","u":"Prise en charge","t":"Connaître les principes de protection en cas d’évènement chimique de grande ampleur","q":"Quelle est la conduite à tenir immédiate pour un individu se trouvant sur les lieux d’un accident chimique de grande ampleur ?","a":"<p>Pour un individu sur les lieux d'un accident chimique de grande ampleur, l'urgent est de <strong>fuir la zone</strong>, puis d'appeler les secours.</p>"},{"i":"afd9431dd3ad","n":337,"o":"337-20","u":"Prise en charge","t":"Connaître les principes de protection en cas d’évènement chimique de grande ampleur","q":"Quel est le principe directeur primordial de la prise en charge d'une intoxication aiguë de grande ampleur ?","a":"<p>En cas d'intoxication aiguë de grande ampleur, le principe directeur est de <strong>protéger les lieux de soins et les soignants</strong>. Cela prime sur le soin immédiat des victimes contaminées, afin de préserver la capacité de réponse de l'hôpital.</p>"},{"i":"2176ea6b685d","n":337,"o":"337-23","u":"Epidémiologie","t":"Intoxications aiguës de l’enfant : connaître les circonstances","q":"Quel est le rôle du Centre Antipoison (CAP) dans la gestion des intoxications aiguës chez l'enfant ?","a":"<p>Dans plus de <strong>60 %</strong> des cas, la situation est gérée par téléphone par le <strong>Centre Antipoison (CAP)</strong>, sans consultation médicale nécessaire.</p>"},{"i":"b107378f538c","n":337,"o":"337-23","u":"Epidémiologie","t":"Intoxications aiguës de l’enfant : connaître les circonstances","q":"Quels sont les toxiques fréquemment impliqués dans les intoxications aiguës accidentelles chez l'enfant au domicile ?","a":"<ul><li>Le <strong>paracétamol</strong> est l'antipyrétique/antalgique le plus prescrit, ce qui le rend très disponible et fréquemment impliqué.</li><li>Le <strong>monoxyde de carbone</strong> pour lequel les enfants sont particulièrement vulnérables et représentent environ <strong>20 %</strong> des intoxications.</li><li>Les <strong>produits ménagers</strong>, souvent stockés dans la cuisine, la salle de bains et les toilettes (pièces à risque).</li></ul>"},{"i":"b444d1125d07","n":337,"o":"337-23","u":"Epidémiologie","t":"Intoxications aiguës de l’enfant : connaître les circonstances","q":"Quelles sont les circonstances typiques d'intoxication aiguë chez l'enfant selon les tranches d'âge ?","a":"<ul><li><strong>Avant 1 an</strong> : Erreur d'administration d'un médicament par un parent (dose incorrecte, médicament inapproprié), représentant environ <strong>25 %</strong> des cas.</li><li><strong>Entre 1 et 8 ans</strong> : Intoxication <strong>accidentelle et exploratoire</strong>, impliquant souvent l'ingestion d'un produit unique au domicile.</li><li><strong>Plus de 10 ans / Adolescents</strong> (surtout les filles) : Intoxication plutôt <strong>volontaire/intentionnelle</strong>, volontiers polymédicamenteuse.</li></ul>"},{"i":"e626be52727b","n":337,"o":"337-23","u":"Epidémiologie","t":"Intoxications aiguës de l’enfant : connaître les circonstances","q":"Quelle est la principale différence en termes de circonstances d'intoxication aiguë entre l'enfant et l'adulte ?","a":"<p>Chez l'<strong>enfant</strong>, l'intoxication est le plus souvent <strong>accidentelle et domestique</strong>, à la différence de l'<strong>adulte</strong> où prédomine l'intoxication <strong>volontaire</strong>.</p>"},{"i":"f58849208185","n":337,"o":"337-23","u":"Epidémiologie","t":"Intoxications aiguës de l’enfant : connaître les circonstances","q":"Quels sont les facteurs de risque domestiques et les horaires de pic pour les intoxications aiguës chez l'enfant ?","a":"<ul><li><strong>Horaires de pic</strong> : entre <strong>11h et 13h</strong> et entre <strong>18h et 20h</strong>, souvent liés à la préparation des repas et à une surveillance moindre.</li><li><strong>Pièces à risque</strong> : la <strong>cuisine</strong>, la <strong>salle de bains</strong> et les <strong>toilettes</strong>, en raison de la présence de produits ménagers.</li></ul>"},{"i":"8e2d30eed3ea","n":337,"o":"337-24","u":"Identifier une urgence","t":"Intoxications aiguës de l’enfant : identifier les situations d’urgence selon le terrain et le toxique","q":"Quels sont les facteurs aggravants d'une intoxication au monoxyde de carbone (CO) chez l'enfant imposant une prise en charge urgente ?","a":"<p>Les facteurs aggravants d'une intoxication au CO chez l'enfant, qui imposent une prise en charge urgente, incluent :</p><ul><li>L'<strong>intoxication aux fumées d'incendie</strong></li><li>Les <strong>lésions traumatiques associées</strong></li><li>Une <strong>perte de connaissance</strong></li><li>Un taux d'<strong>HbCO (carboxyhémoglobine) supérieur à 15 %</strong></li></ul>"},{"i":"a790b1cf6bd2","n":337,"o":"337-24","u":"Identifier une urgence","t":"Intoxications aiguës de l’enfant : identifier les situations d’urgence selon le terrain et le toxique","q":"Dans quels cas une administration urgente de N-acétylcystéine est-elle indiquée en cas d'intoxication au paracétamol chez l'enfant ?","a":"<p>L'administration urgente de <strong>N-acétylcystéine</strong> est indiquée en cas d'intoxication au paracétamol chez l'enfant si :</p><ul><li>La <strong>dose ingérée est supérieure à 150 mg/kg</strong></li><li>L'ingestion <strong>date de plus de 8 heures</strong></li><li>Il existe des <strong>signes de toxicité</strong></li><li>Il s'agit d'une <strong>poly-intoxication</strong></li></ul><p>Il existe un risque, rare (moins de 1 % des enfants intoxiqués), d'<strong>hépatite fulminante</strong>.</p>"},{"i":"ac80df1bb4c5","n":337,"o":"337-24","u":"Identifier une urgence","t":"Intoxications aiguës de l’enfant : identifier les situations d’urgence selon le terrain et le toxique","q":"Quand faut-il suspecter une intoxication au monoxyde de carbone (CO) chez un enfant, et quels sont les signes d'urgence que l'on peut attendre ?","a":"<p>Une intoxication au CO doit être suspectée lorsqu'on retrouve des <stong>troubles de conscience</stong> pouvant s'accompagner de <strong>trismus</strong> ou de <strong>convulsions</strong>. On peut également observer :</p><ul><li>Une <strong>HTA</strong>, une <strong>hyperthermie</strong>, une <strong>tachycardie</strong></li><li>Une <strong>détresse respiratoire</strong></li><li>Des <strong>troubles du rythme ou de la repolarisation à l'ECG</strong></li></ul><p>Ces manifestations cliniques doivent faire rechercher une intoxication au CO, notamment en période hivernale ou en présence d'appareils de chauffage défectueux.</p>"},{"i":"b494414b1150","n":337,"o":"337-25","u":"Prise en charge","t":"Intoxications aiguës de l’enfant : connaître les principes de prise en charge","q":"Quelles sont les indications de l'oxygénothérapie hyperbare (OHB) dans l'intoxication au monoxyde de carbone chez l'enfant ?","a":"<p>Les indications de l'oxygénothérapie hyperbare sont larges chez l'enfant et incluent :</p><ul><li>Toute <strong>perte de connaissance</strong>, même brève.</li><li>Les <strong>troubles de la conscience</strong>.</li><li>Les <strong>convulsions</strong>.</li><li>Des <strong>signes neurologiques</strong>.</li><li>Les <strong>troubles du rythme cardiaque</strong>.</li></ul>"},{"i":"ba167be1b39b","n":337,"o":"337-25","u":"Prise en charge","t":"Intoxications aiguës de l’enfant : connaître les principes de prise en charge","q":"Quels sont les principes généraux de prise en charge d'une intoxication aiguë chez l'enfant ?","a":"<p>La prise en charge des intoxications aiguës chez l'enfant suit les mêmes principes que chez l'adulte, à savoir :</p><ul><li>Un <strong>traitement symptomatique</strong> guidé par les défaillances d'organe.</li><li>L'administration d'<strong>antidotes</strong> spécifiques si disponibles.</li></ul>"},{"i":"e80b3a07178c","n":337,"o":"337-25","u":"Prise en charge","t":"Intoxications aiguës de l’enfant : connaître les principes de prise en charge","q":"Quand faut-il administrer la N-acétylcystéine dans le cadre d'une intoxication au paracétamol chez l'enfant ?","a":"<p>La N-acétylcystéine doit être administrée dans plusieurs situations :</p><ul><li><strong>Dès l'arrivée</strong> en cas de <strong>forte suspicion</strong>, de <strong>signes de toxicité</strong>, d'<strong>ingestion > 8 heures</strong>, d'une dose ingérée <strong>> 150 mg/kg</strong> ou en cas de <strong>poly-intoxication</strong>.</li><li>Sinon, elle est administrée <strong>après H4</strong> en fonction de la <strong>paracétamolémie</strong> reportée sur le <strong>nomogramme</strong>.</li></ul>"},{"i":"ed6d6ea6a3d3","n":337,"o":"337-25","u":"Prise en charge","t":"Intoxications aiguës de l’enfant : connaître les principes de prise en charge","q":"Quelle est la prise en charge initiale de l'intoxication au monoxyde de carbone (CO) chez l'enfant en phase pré-hospitalière et hospitalière ?","a":"<ul><li><strong>Phase pré-hospitalière (domicile)</strong> : Appel du <strong>15</strong>, intervention d'une équipe médicalisée avec détecteur de CO, aération des lieux.</li><li><strong>Phase hospitalière initiale</strong> :<br><ul><li>Application de l'approche <strong>ABCDE</strong>.</li><li>Administration d'<strong>oxygène au masque haute concentration</strong> (> 8 L/min) ou intubation/ventilation si troubles de la conscience.</li><li>Dosage précoce de l'<strong>HbCO</strong> et réalisation d'un <strong>ECG</strong>.</li></ul></li><li><strong>Prise en charge hospitalière</strong> : Poursuite de l'<strong>oxygénothérapie</strong> pendant au moins <strong>12 heures</strong>.</li></ul>"},{"i":"5a3ec01a7159","n":337,"o":"337-26","u":"Suivi et/ou pronostic","t":"Intoxications aiguës de l’enfant : savoir prévenir","q":"Quelles sont les mesures préventives clés à mettre en œuvre à domicile pour éviter les intoxications aiguës chez l'enfant ?","a":"<ul><li>Ranger les <strong>médicaments et produits d'entretien hors de portée</strong> des enfants et en hauteur.</li><li>Utiliser des <strong>conditionnements de sécurité</strong> (bouchons pédiatriques, emballage unitaire des médicaments).</li><li>Pour les <strong>caustiques</strong>, généraliser les fermetures sécurisées.</li><li>Ne jamais <strong>transvaser un produit ménager</strong> dans un récipient à usage alimentaire et bien distinguer les contenants.</li></ul>"},{"i":"64c1dda2f924","n":337,"o":"337-26","u":"Suivi et/ou pronostic","t":"Intoxications aiguës de l’enfant : savoir prévenir","q":"Pourquoi est-il crucial de ne jamais transvaser un produit ménager dans un récipient alimentaire, dans le cadre de la prévention des intoxications chez l'enfant ?","a":"<p>Il est crucial de ne jamais transvaser un produit ménager dans un récipient à usage alimentaire (comme une bouteille de boisson) afin d'<strong>éviter toute confusion</strong> par l'enfant, qui pourrait ingérer le produit toxique en pensant qu'il s'agit d'une boisson ou d'un aliment. Cela inclut aussi de bien <strong>distinguer visuellement les contenants alimentaires des contenants ménagers</strong>.</p>"},{"i":"8ef2bf0f036a","n":337,"o":"337-26","u":"Suivi et/ou pronostic","t":"Intoxications aiguës de l’enfant : savoir prévenir","q":"Quelle est l'une des principales mesures institutionnelles pour la prévention des intoxications aiguës chez l'enfant, notamment celles au monoxyde de carbone ?","a":"<p>La prévention repose sur les <strong>obligations de signalement</strong>, qui permettent d'identifier les sources et d'éviter les récidives. Pour le <strong>monoxyde de carbone (CO)</strong> en particulier, un signalement obligatoire à l'<strong>ARS via le centre antipoison</strong> est requis, suivi d'une enquête technique.</p>"},{"i":"0346b4715ef9","n":337,"o":"337-4","u":"Diagnostic positif","t":"Connaître les signes cliniques des intoxications aiguës","q":"Comment l'examen des pupilles peut-il orienter vers une famille de toxiques lors d'une intoxication aiguë ?","a":"<p>L'examen des pupilles est un élément clé d'orientation :</p><ul><li>Un <strong>myosis</strong> (pupilles serrées) oriente vers les <strong>opioïdes</strong>, les organophosphorés, les barbituriques ou les phénothiazines.</li><li>Une <strong>mydriase</strong> (pupilles dilatées) oriente vers les tricycliques, l'atropine, la cocaïne/amphétamines ou les ISRS.</li></ul>"},{"i":"0ecd1d5db3b1","n":337,"o":"337-4","u":"Diagnostic positif","t":"Connaître les signes cliniques des intoxications aiguës","q":"Quels sont les signes cliniques majeurs du syndrome sérotoninergique ?","a":"<p>Le syndrome sérotoninergique se caractérise par :</p><ul><li>Une <strong>hyperthermie (40-43 °C)</strong>.</li><li>Des <strong>myoclonies</strong> et <strong>hyperréflexie</strong>.</li><li>Une <strong>rigidité</strong> et un syndrome pyramidal.</li><li>Une <strong>mydriase</strong>.</li></ul><p>Il peut être induit par les ISRS, d'autres antidépresseurs, le tramadol, la MDMA ou la cocaïne. Les complications graves incluent le choc, la CIVD et la rhabdomyolyse.</p>"},{"i":"440b776daea8","n":337,"o":"337-4","u":"Diagnostic positif","t":"Connaître les signes cliniques des intoxications aiguës","q":"Quels sont les signes clés d'un toxidrome anticholinergique ou atropinique ?","a":"<p>Le toxidrome anticholinergique se caractérise par :</p><ul><li>Une <strong>mydriase peu réactive</strong>.</li><li>Un <strong>coma agité avec hyperréflexie</strong>.</li><li>Une <strong>hyperthermie</strong> et un <strong>flush cutané</strong>.</li><li>Une <strong>sécheresse des muqueuses</strong>.</li><li>Une <strong>tachycardie</strong>.</li><li>Une <strong>rétention urinaire</strong>.</li></ul><p>Ces manifestations sont souvent dues aux antidépresseurs tricycliques, aux antipsychotiques, aux anti-H1 ou à l'atropine.</p>"},{"i":"6afb010db1d3","n":337,"o":"337-4","u":"Diagnostic positif","t":"Connaître les signes cliniques des intoxications aiguës","q":"Comment définir un toxidrome dans le contexte des intoxications aiguës ?","a":"<p>Un toxidrome est un ensemble de <strong>signes cliniques et biologiques cohérents</strong>, qui permet d'orienter vers une <strong>famille pharmacologique</strong> spécifique de toxiques lors d'une intoxication aiguë.</p>"},{"i":"8702356886d2","n":337,"o":"337-4","u":"Diagnostic positif","t":"Connaître les signes cliniques des intoxications aiguës","q":"Quels sont les signes distinctifs du toxidrome adrénergique ou sympathomimétique ?","a":"<p>Le toxidrome adrénergique (MATCH) se manifeste par :</p><ul><li><strong>M</strong>ydriase.</li><li><strong>A</strong>gitation.</li><li><strong>C</strong>oma / <strong>C</strong>onvulsions.</li><li><strong>T</strong>achycardie / <strong>H</strong>yper<strong>T</strong>hermie / <strong>H</strong>yper<strong>T</strong>ension artérielle.</li><li><strong>H</strong>yperventilation.</li></ul><p>Il est souvent causé par la cocaïne, les amphétamines, le LSD ou les xanthines.</p>"},{"i":"b1384e24e558","n":337,"o":"337-4","u":"Diagnostic positif","t":"Connaître les signes cliniques des intoxications aiguës","q":"Quelle est la triade classique du toxidrome morphinique ou opioïde ?","a":"<p>La triade classique du toxidrome morphinique est :</p><ul><li>Un <strong>coma calme, hypotonique, aréflexique</strong>.</li><li>Un <strong>myosis serré bilatéral</strong>.</li><li>Une <strong>bradyplnée &le; 10/min</strong>.</li></ul><p>On peut également retrouver un globe urinaire. La principale gravité est la détresse respiratoire pouvant mener à un arrêt cardiorespiratoire hypoxique.</p>"},{"i":"1586be5e666d","n":337,"o":"337-5","u":"Diagnostic positif","t":"Reconnaître les signes de gravité des intoxications aiguës chez l’adulte","q":"Quels sont les signes de gravité à rechercher en cas de toxidrome anticholinergique chez un patient intoxiqué ?","a":"<p>En cas de toxidrome <strong>anticholinergique</strong>, les signes de gravité comprennent :</p><ul><li>Le <strong>coma</strong>.</li><li>La <strong>rétention aiguë d'urine</strong>.</li><li>L'<strong>effet stabilisant de membrane</strong>.</li></ul>"},{"i":"5554f1a75959","n":337,"o":"337-5","u":"Diagnostic positif","t":"Reconnaître les signes de gravité des intoxications aiguës chez l’adulte","q":"Quels sont les signes de gravité spécifiques d'un toxidrome adrénergique ou sérotoninergique dans une intoxication aiguë ?","a":"<p>Les signes de gravité spécifiques sont :</p><ul><li>Pour un toxidrome <strong>adrénergique</strong> : le <strong>choc cardiogénique</strong>.</li><li>Pour un toxidrome <strong>sérotoninergique</strong> : le <strong>choc</strong>, le <strong>coma</strong>, la <strong>CIVD</strong> (coagulation intravasculaire disséminée) et la <strong>rhabdomyolyse</strong>.</li></ul>"},{"i":"910f4e6e4d2f","n":337,"o":"337-5","u":"Diagnostic positif","t":"Reconnaître les signes de gravité des intoxications aiguës chez l’adulte","q":"Quels sont les signes de gravité immédiate à évaluer dans le cadre d'une intoxication aiguë chez l'adulte dès les premières secondes ?","a":"<p>Dès les premières secondes, l'évaluation de la gravité immédiate se focalise sur :</p><ul><li>La <strong>conscience</strong> : appréciation avec le score de Glasgow.</li><li>La <strong>ventilation</strong> : évaluation de la SaO₂, la fréquence respiratoire (FR), la présence d'encombrement ou d'obstruction pharyngée.</li><li>L'<strong>hémodynamique</strong> : recherche d'un arrêt cardiaque ou de signes de choc.</li><li>Sytématiquement : la <strong>glycémie capillaire</strong> et la <strong>température</strong>.</li></ul>"},{"i":"c16d4c7a9455","n":337,"o":"337-5","u":"Diagnostic positif","t":"Reconnaître les signes de gravité des intoxications aiguës chez l’adulte","q":"Quelle est l'importance de l'évaluation dynamique de la conscience et des défaillances d'organes lors de la prise en charge d'une intoxication aiguë ?","a":"<p>En toxicologie, l'évaluation des défaillances d'organes est un processus <strong>dynamique et à répéter</strong>. Il est fréquent qu'un patient initialement conscient s'aggrave vers le coma au cours de la prise en charge. Un score de Glasgow <strong>inférieur ou égal à 8</strong> impose une <strong>protection des voies aériennes</strong>.</p>"},{"i":"c4b8487eda58","n":337,"o":"337-5","u":"Diagnostic positif","t":"Reconnaître les signes de gravité des intoxications aiguës chez l’adulte","q":"Lors d'une intoxication aiguë, quels sont les signes de gravité spécifiques du toxidrome morphinique/myorelaxant ?","a":"<p>Pour un toxidrome <strong>morphinique ou myorelaxant</strong>, le signe de gravité principal est la <strong>détresse respiratoire</strong>.</p>"},{"i":"608fba314619","n":337,"o":"337-7","u":"Diagnostic positif","t":"Savoir suspecter un évènement chimique de grande ampleur","q":"Quels sont les critères cliniques et épidémiologiques permettant de suspecter une intoxication chimique de grande ampleur ?","a":"<p>La suspicion survient lorsque <strong>plusieurs personnes</strong> provenant du <strong>même endroit</strong> se présentent avec les <strong>mêmes symptômes</strong>.</p>"},{"i":"655b0e0f64ad","n":337,"o":"337-7","u":"Diagnostic positif","t":"Savoir suspecter un évènement chimique de grande ampleur","q":"Quelle est la priorité de prise en charge lors de la suspicion d'un événement chimique de grande ampleur ?","a":"<p>La priorité est d'abord d'<strong>anticiper et de se protéger</strong>, avant même le soin des victimes, en raison des risques pour les intervenants.</p>"},{"i":"74000fda2b5a","n":337,"o":"337-7","u":"Diagnostic positif","t":"Savoir suspecter un évènement chimique de grande ampleur","q":"Dans quel contexte doit-on évoquer la suspicion d'un événement chimique de grande ampleur ?","a":"<p>Une intoxication de grande ampleur doit être suspectée dans le cadre d'une utilisation comme <strong>arme militaire ou terroriste</strong>, ou lors d'un <strong>accident industriel</strong>.</p>"},{"i":"bd443fefaafb","n":337,"o":"337-7","u":"Diagnostic positif","t":"Savoir suspecter un évènement chimique de grande ampleur","q":"Quelles sont les principales catégories de substances toxiques pouvant être impliquées dans un événement chimique de grande ampleur ?","a":"<ul><li>Les <strong>neurotoxiques</strong>.</li><li>Les <strong>irritants des voies respiratoires</strong> (pouvant aller jusqu'au <strong>SDRA</strong>).</li><li>Les <strong>asphyxiants</strong>.</li></ul>"}]};